// Cloudflare Worker for FinPress
const HTML = "<!DOCTYPE html>\n<html lang=\"en\" class=\"h-full antialiased\" data-theme=\"light\">\n<head>\n  <meta charset=\"utf-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=5, viewport-fit=cover\"/>\n  <title>FinPress Institutional Workspace \u2014 Trader Terminal</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['\"DM Sans\"', '\"Plus Jakarta Sans\"', 'system-ui', '-apple-system', 'BlinkMacSystemFont', 'sans-serif'],\n            mono: ['\"JetBrains Mono\"', 'monospace'],\n          },\n          colors: {\n            brand: { 50: '#EEF2FF', 100: '#E0E7FF', 500: '#6366F1', 600: '#4F46E5', 700: '#4338CA' }\n          }\n        }\n      }\n    };\n  </script>\n  <style>\n    *, *::before, *::after {\n      box-sizing: border-box !important;\n    }\n    html, body {\n      width: 100% !important;\n      min-width: 100% !important;\n      max-width: 100% !important;\n      height: 100% !important;\n      min-height: 100% !important;\n      margin: 0 !important;\n      padding: 0 !important;\n      overflow: hidden !important;\n      touch-action: manipulation;\n      -webkit-text-size-adjust: 100%;\n      background-color: #F1F5F9;\n    }\n    body {\n      font-family: 'DM Sans', 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n      font-size: 13px;\n      font-weight: 400;\n      color: #090D16;\n      -webkit-font-smoothing: antialiased;\n      -moz-osx-font-smoothing: grayscale;\n      text-rendering: optimizeLegibility;\n      background-color: #F1F5F9;\n    }\n    .dark body {\n      background-color: #070B14;\n    }\n    .font-mono { font-family: 'JetBrains Mono', monospace; }\n    ::-webkit-scrollbar { width: 6px; height: 6px; }\n    ::-webkit-scrollbar-track { background: transparent; }\n    ::-webkit-scrollbar-thumb { background: #CBD5E1; border-radius: 4px; }\n    .dark ::-webkit-scrollbar-thumb { background: #334155; }\n    .table-row-hover:hover { background-color: rgba(99, 102, 241, 0.05); }\n    .dark .table-row-hover:hover { background-color: rgba(99, 102, 241, 0.10); }\n    mark { background-color: #FEF08A; color: #854D0E; padding: 0 2px; border-radius: 2px; font-weight: 700; }\n    .dark mark { background-color: #854D0E; color: #FEF08A; }\n\n    /* Strict visibility classes */\n    .hidden {\n      display: none !important;\n    }\n\n    /* Fixed Viewport Edge-to-Edge Layout */\n    #app-root {\n      width: 100% !important;\n      min-width: 100% !important;\n      max-width: 100% !important;\n      height: 100% !important;\n      min-height: 100% !important;\n      display: flex !important;\n      flex-direction: column !important;\n      overflow: hidden !important;\n      margin: 0 !important;\n      padding: 0 !important;\n    }\n    #app-header {\n      width: 100% !important;\n      max-width: 100% !important;\n      min-width: 100% !important;\n      height: 48px !important;\n      min-height: 48px !important;\n      flex-shrink: 0 !important;\n      z-index: 50 !important;\n    }\n    #app-main {\n      width: 100% !important;\n      max-width: 100% !important;\n      min-width: 100% !important;\n      flex: 1 1 0% !important;\n      padding: 6px 8px 8px 8px !important;\n      display: flex !important;\n      flex-direction: column !important;\n      overflow: hidden !important;\n      min-height: 0 !important;\n      background-color: #F1F5F9;\n      gap: 6px !important;\n    }\n    .dark #app-main {\n      background-color: #070B14;\n    }\n\n    /* Main Workspace Grid (Views Container + Permanent 3rd Column Sidebar) */\n    #workspace-grid {\n      width: 100% !important;\n      max-width: 100% !important;\n      min-width: 100% !important;\n      flex: 1 1 0% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      display: grid !important;\n      grid-template-columns: minmax(0, 1fr) 280px !important;\n      grid-template-rows: 100% !important;\n      gap: 8px !important;\n      overflow: hidden !important;\n    }\n    @media (min-width: 1280px) {\n      #workspace-grid {\n        grid-template-columns: minmax(0, 1fr) 320px !important;\n      }\n    }\n    @media (min-width: 1536px) {\n      #workspace-grid {\n        grid-template-columns: minmax(0, 1fr) 360px !important;\n      }\n    }\n    @media (min-width: 1920px) {\n      #workspace-grid {\n        grid-template-columns: minmax(0, 1fr) 380px !important;\n      }\n    }\n    @media (min-width: 2560px) {\n      #workspace-grid {\n        grid-template-columns: minmax(0, 1fr) 420px !important;\n      }\n    }\n    #workspace-grid.sidebar-collapsed {\n      grid-template-columns: minmax(0, 1fr) !important;\n    }\n\n    #workspace-views {\n      width: 100% !important;\n      max-width: 100% !important;\n      min-width: 0 !important;\n      flex: 1 1 0% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      overflow: hidden !important;\n      display: flex !important;\n      flex-direction: column !important;\n    }\n\n    #view-feed:not(.hidden) {\n      width: 100% !important;\n      max-width: 100% !important;\n      min-width: 100% !important;\n      flex: 1 1 0% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      display: grid !important;\n      grid-template-columns: 290px minmax(0, 1fr) !important;\n      grid-template-rows: 100% !important;\n      gap: 8px !important;\n      overflow: hidden !important;\n    }\n    @media (min-width: 1280px) {\n      #view-feed:not(.hidden) {\n        grid-template-columns: 320px minmax(0, 1fr) !important;\n      }\n    }\n    @media (min-width: 1536px) {\n      #view-feed:not(.hidden) {\n        grid-template-columns: 350px minmax(0, 1fr) !important;\n      }\n    }\n    @media (min-width: 1920px) {\n      #view-feed:not(.hidden) {\n        grid-template-columns: 380px minmax(0, 1fr) !important;\n      }\n    }\n    @media (min-width: 2560px) {\n      #view-feed:not(.hidden) {\n        grid-template-columns: 420px minmax(0, 1fr) !important;\n      }\n    }\n    #view-feed.feed-col1-collapsed {\n      grid-template-columns: minmax(0, 1fr) !important;\n    }\n\n    #view-ipo:not(.hidden) {\n      width: 100% !important;\n      max-width: 100% !important;\n      min-width: 100% !important;\n      flex: 1 1 0% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      display: flex !important;\n      flex-direction: column !important;\n      gap: 8px !important;\n      overflow: hidden !important;\n    }\n\n    #col-news-wire {\n      width: 100% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      display: flex !important;\n      flex-direction: column !important;\n      overflow: hidden !important;\n    }\n    #feed-list-container {\n      flex: 1 1 0% !important;\n      min-height: 0 !important;\n      overflow-y: auto !important;\n    }\n\n    #feed-detail-wrapper {\n      width: 100% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      display: flex !important;\n      flex-direction: column !important;\n      overflow-y: auto !important;\n    }\n    #feed-detail-container {\n      width: 100% !important;\n      flex: 1 1 0% !important;\n      min-height: 0 !important;\n      display: flex !important;\n      flex-direction: column !important;\n    }\n\n    #view-feed-aside {\n      width: 100% !important;\n      height: 100% !important;\n      min-height: 0 !important;\n      display: flex !important;\n      flex-direction: column !important;\n      overflow-y: auto !important;\n    }\n    #tree-sidebar-container {\n      width: 100% !important;\n      display: flex !important;\n      flex-direction: column !important;\n      gap: 6px !important;\n    }\n\n    @media (max-width: 1023px) {\n      #workspace-grid {\n        grid-template-columns: 100% !important;\n        grid-template-rows: auto auto !important;\n        overflow-y: auto !important;\n      }\n      #view-feed:not(.hidden) {\n        grid-template-columns: 100% !important;\n        grid-template-rows: auto auto !important;\n        overflow-y: auto !important;\n      }\n      #app-main {\n        overflow-y: auto !important;\n      }\n    }\n  </style>\n</head>\n<body class=\"min-h-full bg-[#F1F5F9] text-slate-900 dark:bg-[#070B14] dark:text-slate-100 transition-colors duration-150\">\n  <div id=\"app-root\" class=\"w-full h-full min-w-full min-h-full flex flex-col overflow-hidden m-0 p-0 bg-[#F1F5F9] dark:bg-[#070B14]\">\n\n    <!-- ================= 1. UNIFIED TOP NAVIGATION & CONTROLS RIBBON (DARK THEME - ENLARGED) ================= -->\n    <header id=\"app-header\" class=\"shrink-0 w-full bg-[#070B14] border-b border-slate-800 text-slate-100 shadow-lg px-3 sm:px-4 py-2 flex items-center justify-between gap-3 overflow-x-auto whitespace-nowrap text-[13px] font-mono z-50\">\n      \n      <!-- Left: FinPress Branding & Live Market Pulse -->\n      <div class=\"flex items-center gap-4 shrink-0\">\n        <div class=\"flex items-center gap-2.5 shrink-0 cursor-pointer group\" onclick=\"onCategorySelect('ALL')\" title=\"Reset to All Stories\">\n          <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-amber-500 to-amber-700 flex items-center justify-center shadow-md border border-amber-400/40 group-hover:scale-105 transition-transform\">\n            <span class=\"text-white text-[13px] font-extrabold tracking-tight font-mono\">FP</span>\n          </div>\n          <span class=\"text-[19px] sm:text-[21px] font-black tracking-tight text-white font-mono mr-1 drop-shadow-xs\">\n            Fin<span class=\"text-amber-400\">Press</span>\n          </span>\n        </div>\n\n        <!-- Live Market Pulse Key Data in Dark Ribbon -->\n        <div class=\"flex items-center gap-3.5 text-[12px] border-l border-slate-800 pl-4\">\n          <span class=\"text-slate-300 font-medium\">NIFTY <b class=\"text-emerald-400 font-bold font-mono\">24,835 (+0.64%)</b></span>\n          <span class=\"text-slate-300 font-medium\">BANK NIFTY <b class=\"text-emerald-400 font-bold font-mono\">54,120 (+0.82%)</b></span>\n          <span class=\"text-slate-300 font-medium\">INDIA VIX <b class=\"text-rose-400 font-bold font-mono\">12.85 (-3.2%)</b></span>\n          <span class=\"text-slate-300 font-medium\">BRENT <b class=\"text-amber-300 font-bold font-mono\">$74.2/bbl</b></span>\n          <span class=\"text-slate-300 font-medium\">USD/INR <b class=\"text-slate-100 font-bold font-mono\">\u20b983.65</b></span>\n        </div>\n      </div>\n\n      <!-- Right: Search + Calendar + Status + Total + Font + Theme -->\n      <div class=\"flex items-center gap-2.5 shrink-0\">\n        \n        <div class=\"relative w-40 sm:w-52\">\n          <input type=\"text\" id=\"global-search\" oninput=\"onSearchInput()\" placeholder=\"Search stock or news...\" class=\"w-full text-[12px] pl-7 pr-6 py-1.5 rounded-lg border border-slate-700 bg-slate-900 text-slate-100 placeholder-slate-400 focus:outline-none focus:border-amber-500 font-mono shadow-2xs\"/>\n          <span class=\"absolute left-2 top-2 text-slate-400 text-[11px]\">\ud83d\udd0d</span>\n          <button id=\"clear-search-btn\" onclick=\"clearSearch()\" class=\"hidden absolute right-2 top-1.5 text-slate-400 hover:text-white text-[12px] font-bold p-0.5\">\u2715</button>\n        </div>\n\n        <!-- Historical Calendar & Edition Navigation -->\n        <div class=\"flex items-center gap-1 bg-slate-900 p-1 rounded-lg border border-slate-700 font-mono text-[12px]\">\n          <button onclick=\"navigateDate(-1)\" class=\"px-2 py-0.5 rounded hover:bg-slate-800 text-slate-300 hover:text-white font-bold\" title=\"Previous Date (\u25c0)\">\u25c0</button>\n          <div class=\"flex items-center gap-1 px-1.5 py-0.5 bg-black/60 rounded border border-slate-800\">\n            <span class=\"text-slate-400 text-[11px]\">\ud83d\udcc5</span>\n            <input type=\"date\" id=\"calendar-picker\" onchange=\"onCalendarSelect(this.value)\" class=\"bg-transparent text-slate-100 font-bold font-mono text-[12px] focus:outline-none cursor-pointer [color-scheme:dark] max-w-[110px]\"/>\n          </div>\n          <button onclick=\"navigateDate(1)\" class=\"px-2 py-0.5 rounded hover:bg-slate-800 text-slate-300 hover:text-white font-bold\" title=\"Next Date (\u25b6)\">\u25b6</button>\n        </div>\n\n        <div id=\"source-health-container\" class=\"flex items-center gap-1.5 font-mono text-[11px]\"></div>\n\n        <span id=\"total-news-counter-badge\" class=\"px-2.5 py-1 rounded-lg bg-emerald-500/15 border border-emerald-500/40 text-emerald-300 font-extrabold font-mono text-[12.5px] shadow-xs\">\n          \ud83d\udd25 <b id=\"top-total-count\">0</b> Stories\n        </span>\n\n        <!-- Font Size Controls -->\n        <div class=\"flex items-center bg-slate-900 p-1 rounded-lg border border-slate-700 text-[11.5px] font-mono font-semibold\">\n          <button onclick=\"adjustFontSize(-1)\" class=\"px-2 py-0.5 rounded text-slate-300 hover:text-white hover:bg-slate-800\" title=\"Decrease Font Size (A-)\">A-</button>\n          <span id=\"font-size-label\" class=\"px-1.5 text-[10.5px] text-slate-400 select-none font-bold\">100%</span>\n          <button onclick=\"adjustFontSize(1)\" class=\"px-2 py-0.5 rounded text-slate-300 hover:text-white hover:bg-slate-800\" title=\"Increase Font Size (A+)\">A+</button>\n        </div>\n\n        <!-- Run Pipeline Trigger Button -->\n        <button id=\"top-ipo-hub-btn\" onclick=\"switchView(currentView === 'ipo' ? 'feed' : 'ipo')\" class=\"px-3 py-1 rounded-lg bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white font-mono text-[12px] font-bold flex items-center gap-1.5 shadow-md transition-transform active:scale-95 cursor-pointer\" title=\"Launch Specialized IPO Intelligence Hub\">\n          <span>\ud83d\ude80</span> <span>IPO Hub</span>\n        </button>\n        <button onclick=\"triggerGitHubPipeline()\" class=\"px-3 py-1 rounded-lg bg-amber-600 hover:bg-amber-700 text-white font-mono text-[12px] font-bold flex items-center gap-1.5 shadow-md transition-transform active:scale-95 cursor-pointer\" title=\"Trigger GitHub Actions pipeline in cloud\">\n          <span>\u26a1</span> <span class=\"hidden sm:inline\">Run Pipeline</span>\n        </button>\n\n        <button onclick=\"toggleTheme()\" class=\"w-8 h-8 rounded-lg border border-slate-700 bg-slate-900 text-slate-300 hover:text-white flex items-center justify-center text-[12.5px] shadow-xs cursor-pointer\" title=\"Toggle Light/Dark Theme\">\n          <span id=\"theme-icon\">\ud83c\udf19</span>\n        </button>\n      </div>\n\n    </header>\n\n    <!-- ================= MAIN THREE-COLUMN WORKSPACE (FULL-WIDTH 3-COLUMN LAYOUT) ================= -->\n    <main id=\"app-main\" class=\"flex-1 w-full flex flex-col overflow-hidden min-h-0 bg-[#F1F5F9] dark:bg-[#070B14] p-1.5 sm:p-2\">\n      \n      <!-- Diagnostic Source Health Alert Banner (Appears when any paper fails) -->\n      <div id=\"source-alert-banner\" class=\"hidden px-3 py-1.5 rounded-lg bg-amber-500/15 border border-amber-500/40 text-amber-900 dark:text-amber-200 text-[11px] font-mono flex items-center justify-between gap-2 shadow-2xs\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-sm\">\u26a0\ufe0f</span>\n          <span id=\"source-alert-text\">Business Standard session failed to authenticate.</span>\n        </div>\n        <button onclick=\"document.getElementById('source-alert-banner').classList.add('hidden')\" class=\"text-slate-400 hover:text-white text-xs font-bold px-1.5 py-0.5\" title=\"Dismiss\">\u2715</button>\n      </div>\n\n      <!-- IPO Central Sub-tabs Header Banner (Appears when IPO Central Desk is active) -->\n      <div id=\"ipo-subtabs-banner\" class=\"hidden rounded-xl bg-white dark:bg-[#0E1322] border border-amber-300/80 dark:border-amber-900/60 p-2 shadow-2xs items-center justify-between gap-2 flex-wrap\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-[12.5px] font-bold font-mono text-amber-950 dark:text-amber-300 flex items-center gap-1.5 px-2\">\n            <span>\ud83d\ude80</span> <span>Primary Market & IPO Intelligence Desk</span>\n          </span>\n          <div class=\"flex items-center bg-slate-100 dark:bg-[#141C33] p-1 rounded-lg border border-slate-200 dark:border-slate-800 text-[12px] font-bold\">\n            <button id=\"ipo-tab-all\" onclick=\"selectIpoSub('ALL')\" class=\"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\">\n              <span>\u2728 All IPOs</span>\n              <span id=\"ipo-sub-all-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-white/20 dark:bg-black/30 font-mono\">0</span>\n            </button>\n            <button id=\"ipo-tab-drhp\" onclick=\"selectIpoSub('DRHP')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udccb DRHP</span>\n              <span id=\"ipo-sub-drhp-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n            <button id=\"ipo-tab-bidding\" onclick=\"selectIpoSub('BIDDING')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udcc8 Bidding</span>\n              <span id=\"ipo-sub-bidding-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n            <button id=\"ipo-tab-notices\" onclick=\"selectIpoSub('NOTICES')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83c\udfdb\ufe0f Allotments</span>\n              <span id=\"ipo-sub-notices-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n          </div>\n        </div>\n        <span class=\"text-[11.5px] font-mono text-slate-500 dark:text-slate-400 font-bold px-2\">\n          DRHP filings, live subscription demand & basis of allotment\n        </span>\n      </div>\n\n      <!-- Corporate Sub-tabs Header Banner (Appears when Corporate Desk is active) -->\n      <div id=\"corporate-subtabs-banner\" class=\"hidden rounded-xl bg-white dark:bg-[#0E1322] border border-indigo-200/90 dark:border-indigo-900/60 p-2 shadow-2xs items-center justify-between gap-2 flex-wrap\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-[12.5px] font-bold font-mono text-indigo-950 dark:text-indigo-300 flex items-center gap-1.5 px-2\">\n            <span>\ud83c\udfe2</span> <span>Corporate Intelligence Desk</span>\n          </span>\n          <div class=\"flex items-center bg-slate-100 dark:bg-[#141C33] p-1 rounded-lg border border-slate-200 dark:border-slate-800 text-[12px] font-bold\">\n            <button id=\"corp-tab-all\" onclick=\"selectCorporateSub('ALL')\" class=\"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\">\n              <span>\ud83c\udfe2 All Corporate</span>\n              <span id=\"corp-sub-all-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-white/20 dark:bg-black/30 font-mono\">0</span>\n            </button>\n            <button id=\"corp-tab-events\" onclick=\"selectCorporateSub('EVENTS')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udce2 Events</span>\n              <span id=\"corp-sub-events-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n            <button id=\"corp-tab-appts\" onclick=\"selectCorporateSub('APPOINTMENTS')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udc54 Appointments</span>\n              <span id=\"corp-sub-appts-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n          </div>\n        </div>\n        <span class=\"text-[11.5px] font-mono text-slate-500 dark:text-slate-400 font-bold px-2\">\n          Disclosures, statutory filings & management appointments\n        </span>\n      </div>\n\n      <!-- ================= VIEW 1: NEWS STREAM (3-COLUMN SIDE-BY-SIDE EXPANDED LAYOUT) ================= -->\n            <!-- Main Workspace Grid (Views Container + Permanent 3rd Column Sidebar) -->\n      <div id=\"workspace-grid\">\n        \n        <!-- Left & Center Area (Views Container) -->\n        <div id=\"workspace-views\">\n          <section id=\"view-feed\">\n        \n        <!-- COLUMN 1: HIGH-DENSITY TERMINAL NEWS WIRE (1-LINER STORIES, MAX 10 PER PAGE) -->\n        <div id=\"col-news-wire\" class=\"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-xs flex flex-col w-full h-full min-h-0\">\n          <div class=\"px-3 py-2 border-b border-slate-200 dark:border-slate-800 bg-slate-100/90 dark:bg-slate-900/80 flex items-center justify-between text-[12px] font-mono shrink-0\">\n            <span id=\"feed-list-count\" class=\"font-extrabold text-slate-900 dark:text-slate-100\">0 Stories</span>\n            <div class=\"flex items-center gap-1\">\n              <button onclick=\"navigateStory(-1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[11px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700\" title=\"Previous Story (Left / Up Arrow or K)\">\u25c0 Prev</button>\n              <button onclick=\"navigateStory(1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[11px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700\" title=\"Next Story (Right / Down Arrow or J)\">Next \u25b6</button>\n              <button onclick=\"toggleCol1()\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-amber-100 hover:text-amber-800 text-[11px] font-bold text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700 cursor-pointer\" title=\"Collapse Column 1 (News Wire)\">\u00ab</button>\n            </div>\n          </div>\n\n          <div id=\"feed-list-container\" class=\"divide-y divide-slate-100 dark:divide-slate-800/80 flex flex-col p-1.5 flex-1 min-h-0 overflow-y-auto\">\n            <!-- Dynamically populated 1-liner story items (Max 10) -->\n          </div>\n\n          <!-- COLUMN 1 PAGINATION BAR (10 STORIES PER PAGE) -->\n          <div id=\"feed-pagination\" class=\"px-3 py-2 border-t border-slate-200 dark:border-slate-800 bg-slate-50/90 dark:bg-slate-900/80 flex items-center justify-between text-[12px] font-mono shrink-0 mt-auto\">\n            <span id=\"feed-pagination-info\" class=\"font-bold text-slate-700 dark:text-slate-300\">Page 1 / 1</span>\n            <div class=\"flex items-center gap-1\">\n              <button id=\"feed-prev-page\" onclick=\"changeFeedPage(-1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[11px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs\">\u25c0 Prev</button>\n              <button id=\"feed-next-page\" onclick=\"changeFeedPage(1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[11px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs\">Next \u25b6</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- COLUMN 2: ACTIVE STORY DEEP DIVE & CATALYST INTELLIGENCE (WIDE READING PANE) -->\n        <div id=\"feed-detail-wrapper\" class=\"w-full h-full rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 p-4 sm:p-5 shadow-xs flex flex-col gap-3 min-h-0 overflow-y-auto\">\n          <div id=\"feed-detail-container\" class=\"w-full flex-1 flex flex-col\">\n            <!-- Dynamically populated active story intelligence -->\n          </div>\n        </div>\n\n        <!-- COLUMN 3: RIGHT HAND SIDE PANEL (TREE DESKS & SECTORS) -->\n        \n\n      </section>\n\n      <!-- ================= VIEW 2: TABULAR IPO CENTRAL ================= -->\n      \n\n      <!-- ================= VIEW 3: TABULAR MASTER NEWS MATRIX (INSTITUTIONAL TABLE) ================= -->\n\n      <!-- DEDICATED IPO INTELLIGENCE HUB SECTION -->\n      <section id=\"view-ipo\" class=\"hidden rounded-xl border border-slate-300 dark:border-slate-800 bg-white dark:bg-[#0E1322] shadow-xs p-3 flex-1 flex flex-col min-h-0 overflow-hidden\">\n        \n        <!-- IPO Header Bar & Filters -->\n        <div class=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2 pb-2.5 border-b border-slate-200 dark:border-slate-800 shrink-0\">\n          \n          <div class=\"flex items-center gap-2\">\n            <div class=\"flex items-center gap-1.5 p-0.5 rounded-lg bg-slate-100 dark:bg-slate-900 border border-slate-300 dark:border-slate-800 text-xs font-mono font-bold shadow-2xs\">\n              <button id=\"ipo-mode-tracker-btn\" onclick=\"setIpoViewMode('tracker')\" class=\"px-3 py-1.5 rounded-lg bg-[#1C1917] text-white dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer\">\n                <span>\ud83d\ude80</span> <span>Primary Issues & Pipeline</span>\n              </button>\n              <button id=\"ipo-mode-listed-btn\" onclick=\"setIpoViewMode('listed')\" class=\"px-3 py-1.5 rounded-lg text-slate-700 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 cursor-pointer\">\n                <span>\ud83d\udcc8</span> <span>Listing Performance Track</span>\n              </button>\n            </div>\n          </div>\n\n          <div class=\"flex items-center gap-2 w-full sm:w-auto\">\n            <!-- Search in IPO Hub -->\n            <div class=\"relative flex-1 sm:w-64\">\n              <input type=\"text\" id=\"ipo-hub-search\" oninput=\"onIpoSearchInput(this.value)\" placeholder=\"Search company, exchange, stage...\" class=\"w-full text-xs px-2.5 py-1.5 rounded-lg bg-slate-100 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:border-indigo-500 font-mono shadow-2xs\">\n            </div>\n\n            <!-- Subfilter (Mainboard / SME) -->\n            <div id=\"ipo-subfilter-container\" class=\"flex items-center gap-1 bg-slate-100 dark:bg-slate-900 p-0.5 rounded-lg border border-slate-300 dark:border-slate-800 text-[11px] font-mono\">\n              <button id=\"ipo-filter-all\" onclick=\"setIpoFilterCategory('ALL')\" class=\"px-2.5 py-1 rounded-md bg-slate-900 text-white dark:bg-indigo-600 dark:text-white font-bold shadow-2xs\">All</button>\n              <button id=\"ipo-filter-mb\" onclick=\"setIpoFilterCategory('MAINBOARD')\" class=\"px-2.5 py-1 rounded-md text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800\">Mainboard</button>\n              <button id=\"ipo-filter-sme\" onclick=\"setIpoFilterCategory('SME')\" class=\"px-2.5 py-1 rounded-md text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800\">SME Emerge</button>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- IPO KPI Metrics Strip -->\n        <div id=\"ipo-kpi-strip\" class=\"grid grid-cols-2 sm:grid-cols-4 gap-2.5 py-2 shrink-0\">\n          <div class=\"p-2.5 rounded-lg bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800/80 flex items-center justify-between\">\n            <div>\n              <span class=\"text-[11px] font-mono text-slate-400 uppercase tracking-wider block\">Total Active Issues</span>\n              <span id=\"ipo-kpi-total\" class=\"text-lg font-bold font-mono text-slate-900 dark:text-white\">--</span>\n            </div>\n            <span class=\"text-xl\">\ud83d\udcca</span>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-emerald-50/60 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-900/40 flex items-center justify-between\">\n            <div>\n              <span class=\"text-[11px] font-mono text-emerald-700 dark:text-emerald-400 uppercase tracking-wider block\">Open for Bidding</span>\n              <span id=\"ipo-kpi-bidding\" class=\"text-lg font-bold font-mono text-emerald-900 dark:text-emerald-300\">--</span>\n            </div>\n            <span class=\"text-xl\">\ud83d\udfe2</span>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-amber-50/60 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900/40 flex items-center justify-between\">\n            <div>\n              <span class=\"text-[11px] font-mono text-amber-700 dark:text-amber-400 uppercase tracking-wider block\">DRHP Filed / Pipeline</span>\n              <span id=\"ipo-kpi-drhp\" class=\"text-lg font-bold font-mono text-amber-900 dark:text-amber-300\">--</span>\n            </div>\n            <span class=\"text-xl\">\ud83d\udccb</span>\n          </div>\n          <div class=\"p-2.5 rounded-lg bg-purple-50/60 dark:bg-purple-950/30 border border-purple-200 dark:border-purple-900/40 flex items-center justify-between\">\n            <div>\n              <span class=\"text-[11px] font-mono text-purple-700 dark:text-purple-400 uppercase tracking-wider block\">Avg Grey Market Prem.</span>\n              <span id=\"ipo-kpi-gmp\" class=\"text-lg font-bold font-mono text-purple-900 dark:text-purple-300\">+38.5%</span>\n            </div>\n            <span class=\"text-xl\">\ud83d\udd25</span>\n          </div>\n        </div>\n\n        <!-- Dynamic Tables View Container -->\n        <div class=\"flex-1 min-h-0 flex flex-col overflow-hidden\">\n          \n          <!-- Primary Issues Table Container -->\n          <div id=\"ipo-tracker-table-wrap\" class=\"flex-1 min-h-0 overflow-y-auto rounded-lg border border-slate-200 dark:border-slate-800\">\n            <table class=\"w-full text-left text-xs border-collapse\">\n              <thead class=\"sticky top-0 z-10 bg-slate-100 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 font-mono text-[11px] uppercase tracking-wider text-slate-500 dark:text-slate-400 select-none\">\n                <tr>\n                  <th class=\"py-2.5 px-3 text-center w-12\">#</th>\n                  <th class=\"py-2.5 px-3 min-w-[200px]\">Company / Issuer</th>\n                  <th class=\"py-2.5 px-3\">Bidding Dates</th>\n                  <th class=\"py-2.5 px-3\">Price Band</th>\n                  <th class=\"py-2.5 px-3\">Issue Size</th>\n                  <th class=\"py-2.5 px-3\">Lot Size</th>\n                  <th class=\"py-2.5 px-3\">Subscription (Times)</th>\n                  <th class=\"py-2.5 px-3\">Status / Stage</th>\n                  <th class=\"py-2.5 px-3 text-center\">Intel</th>\n                </tr>\n              </thead>\n              <tbody id=\"ipo-table-body\" class=\"divide-y divide-slate-100 dark:divide-slate-800/80 font-sans\">\n                <!-- Populated dynamically -->\n              </tbody>\n            </table>\n          </div>\n\n          <!-- Already Listed Benchmark Performance Table Container -->\n          <div id=\"ipo-listed-table-wrap\" class=\"hidden flex-1 min-h-0 overflow-y-auto rounded-lg border border-slate-200 dark:border-slate-800\">\n            <table class=\"w-full text-left text-xs border-collapse\">\n              <thead class=\"sticky top-0 z-10 bg-slate-100 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 font-mono text-[11px] uppercase tracking-wider text-slate-500 dark:text-slate-400 select-none\">\n                <tr>\n                  <th class=\"py-2.5 px-3 text-center w-12\">#</th>\n                  <th class=\"py-2.5 px-3 min-w-[180px]\">Company Name</th>\n                  <th class=\"py-2.5 px-3\">Listing Date</th>\n                  <th class=\"py-2.5 px-3\">Issue Price</th>\n                  <th class=\"py-2.5 px-3\">Listing Price</th>\n                  <th class=\"py-2.5 px-3\">Listing Day Gain</th>\n                  <th class=\"py-2.5 px-3\">CMP (Live)</th>\n                  <th class=\"py-2.5 px-3\">Current Gain %</th>\n                  <th class=\"py-2.5 px-3\">Performance Tier</th>\n                </tr>\n              </thead>\n              <tbody id=\"ipo-listed-table-body\" class=\"divide-y divide-slate-100 dark:divide-slate-800/80 font-sans\">\n                <!-- Populated dynamically -->\n              </tbody>\n            </table>\n          </div>\n\n        </div>\n\n      </section>\n        </div>\n\n        <aside id=\"view-feed-aside\" class=\"w-full h-full flex flex-col gap-1.5 min-h-0 overflow-y-auto select-none\">\n          \n          <!-- Tree Container (Renders 1. Categories Card, 2. Sectors Card, 3. Clustered Stocks Card) -->\n          <div id=\"tree-sidebar-container\" class=\"flex flex-col gap-1.5 font-sans w-full\">\n            <!-- Dynamically populated -->\n          </div>\n\n        </aside>\n\n      </div>\n\n    </main>\n\n  </div>\n\n  <!-- ================= STORY FULL DETAILS MODAL ================= -->\n  <div id=\"story-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-3xl w-full p-6 shadow-2xl flex flex-col gap-4 max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span id=\"story-modal-category\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200\">Policy</span>\n            <span id=\"story-modal-sentiment\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-emerald-50 text-emerald-800 border border-emerald-200\">\ud83d\udfe2 BULLISH</span>\n            <span id=\"story-modal-pages\" class=\"text-xs font-mono text-slate-500\">FE (Page 1)</span>\n          </div>\n          <h2 id=\"story-modal-headline\" class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1 leading-tight\">Headline</h2>\n        </div>\n        <button onclick=\"closeStoryModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center shrink-0\">\u2715</button>\n      </div>\n\n      <div id=\"story-modal-tickers-container\" class=\"flex items-center gap-1.5 flex-wrap\">\n        <!-- Tickers -->\n      </div>\n\n      <!-- \u26a1 EXECUTIVE GIST (INDIGO CARD) -->\n      <div class=\"p-3 rounded-xl bg-indigo-50/80 dark:bg-[#10182E] border border-indigo-200/90 dark:border-indigo-800 shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-extrabold text-indigo-950 dark:text-indigo-300 mb-1 flex items-center gap-1\">\n          <span>\u26a1</span> <span>1. Executive Gist (Core Takeaway)</span>\n        </p>\n        <div id=\"story-modal-brief\" class=\"space-y-1.5\"></div>\n      </div>\n\n      <!-- \ud83d\udca1 TRADER CATALYST (DYNAMIC EMERALD/ROSE/SLATE CARD - DIRECTLY BELOW GIST) -->\n      <div id=\"story-modal-catalyst-box\" class=\"p-3 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-[#11172A] shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-slate-600 dark:text-slate-300 mb-1 flex items-center gap-1\">\n          <span>\ud83d\udca1</span> <span>2. Trader Catalyst & Market Impact</span>\n        </p>\n        <div id=\"story-modal-catalyst\" class=\"text-xs text-slate-800 dark:text-slate-200 leading-relaxed font-medium bg-white dark:bg-[#0B1020] p-2.5 rounded-lg border border-slate-200/80 dark:border-slate-800\"></div>\n      </div>\n\n      <!-- \ud83d\udccc KEY ANALYST DATA POINTS (NEWSPAPER BROADSHEET CARD) -->\n      <div class=\"p-3 rounded-xl bg-[#F5EFEB] dark:bg-[#1E1914]/70 border border-[#B8A38E]/80 dark:border-[#524434] shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-extrabold text-[#2E1F14] dark:text-[#F3ECE4] mb-1.5 flex items-center gap-1\">\n          <span>\ud83d\udccc</span> <span>3. Key Analyst Data Points</span>\n        </p>\n        <ul id=\"story-modal-bullets\" class=\"space-y-1.5\">\n          <!-- Bullets -->\n        </ul>\n      </div>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono text-slate-400\">\n        <span id=\"story-modal-source\">FinPress Intelligence</span>\n        <button onclick=\"closeStoryModal()\" class=\"px-4 py-1.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= IPO FULL DETAILS MODAL ================= -->\n  <div id=\"ipo-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-2xl w-full p-6 shadow-2xl flex flex-col gap-4\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span id=\"modal-ipo-exchange\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-indigo-50 text-indigo-700 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300\">NSE / BSE</span>\n            <span id=\"modal-ipo-stage\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-amber-50 text-amber-800 border border-amber-200\">DRHP Filed</span>\n          </div>\n          <h2 id=\"modal-ipo-company\" class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1\">Company Name</h2>\n        </div>\n        <button onclick=\"closeIpoModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center\">\u2715</button>\n      </div>\n\n      <div class=\"grid grid-cols-2 gap-3 bg-slate-50 dark:bg-[#151B2E] p-3 rounded-xl border border-slate-200/80 dark:border-slate-800 font-mono text-xs\">\n        <div>\n          <span class=\"text-slate-400\">Issue Size:</span>\n          <p id=\"modal-ipo-size\" class=\"text-slate-900 dark:text-white font-bold text-sm\">\u20b90 Cr</p>\n        </div>\n        <div>\n          <span class=\"text-slate-400\">Demand / Subscription:</span>\n          <p id=\"modal-ipo-demand\" class=\"text-emerald-600 dark:text-emerald-400 font-bold text-sm\">Filing Stage</p>\n        </div>\n      </div>\n\n      <div>\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-slate-400 mb-1\">Headline & Filing Announcement</p>\n        <p id=\"modal-ipo-headline\" class=\"text-sm font-bold text-slate-800 dark:text-slate-200\"></p>\n      </div>\n\n      <div>\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-brand-600 dark:text-brand-400 mb-1\">Detailed Analyst Insight & Comprehensive Notes</p>\n        <p id=\"modal-ipo-details\" class=\"text-sm text-slate-700 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-[#11172A] p-3.5 rounded-xl border border-slate-200/80 dark:border-slate-800\"></p>\n      </div>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono text-slate-400\">\n        <span id=\"modal-ipo-source\">Source: FE / BS</span>\n        <button onclick=\"closeIpoModal()\" class=\"px-4 py-1.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n  <!-- ================= BUSINESS STANDARD 1-CLICK AUTH & SYNC MODAL ================= -->\n  <div id=\"bs-sync-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-xl w-full p-6 shadow-2xl flex flex-col gap-4 max-h-[92vh] overflow-y-auto\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-amber-100 text-amber-900 border border-amber-300 dark:bg-amber-950/80 dark:text-amber-200\">\u26a1 1-Click Sync</span>\n            <span class=\"text-xs font-mono text-slate-500\">Business Standard ePaper</span>\n          </div>\n          <h2 class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1 leading-tight\">Sync BS Session & Trigger GitHub Actions</h2>\n        </div>\n        <button onclick=\"closeBsSyncModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center shrink-0\">\u2715</button>\n      </div>\n\n      <div class=\"bg-amber-500/10 border border-amber-500/30 rounded-xl p-4 flex flex-col gap-2.5 text-xs\">\n        <p class=\"font-bold text-amber-900 dark:text-amber-200 flex items-center gap-1.5 text-sm\">\n          <span>\ud83d\udccc</span> <span>Browser Bookmarklet (Drag to Bookmarks Bar)</span>\n        </p>\n        <p class=\"text-slate-700 dark:text-slate-300 leading-relaxed text-[12.5px]\">\n          Drag the orange button below to your <b>Browser Bookmarks Bar</b>. Whenever your session expires, just click it while on <code class=\"bg-black/10 dark:bg-white/10 px-1.5 py-0.5 rounded font-mono font-bold\">epaper.business-standard.com</code>!\n        </p>\n        <div class=\"pt-2 flex items-center gap-3 flex-wrap\">\n          <a id=\"bs-bookmarklet-link\" href=\"#\" class=\"px-4 py-2.5 rounded-lg bg-amber-600 hover:bg-amber-700 text-white font-mono font-bold text-sm shadow-md cursor-grab active:cursor-grabbing inline-flex items-center gap-2 transition-transform hover:scale-105\" title=\"Drag this button to your Bookmarks Bar\">\n            <span>\ud83d\udccc</span> <span>Sync FinPress BS</span>\n          </a>\n          <button onclick=\"copyBookmarkletCode()\" class=\"px-3 py-2 rounded-lg bg-slate-200 dark:bg-slate-800 text-slate-800 dark:text-slate-200 hover:bg-slate-300 font-mono text-xs font-bold shadow-2xs\">\n            \ud83d\udccb Copy Code\n          </button>\n        </div>\n      </div>\n\n      <div class=\"space-y-2 text-xs text-slate-700 dark:text-slate-300\">\n        <p class=\"font-bold text-slate-900 dark:text-slate-100 uppercase tracking-wider font-mono text-[11px]\">How to use in 3 steps:</p>\n        <ol class=\"list-decimal list-inside space-y-1.5 bg-slate-50 dark:bg-slate-900/60 p-3.5 rounded-lg border border-slate-200 dark:border-slate-800 text-[12.5px]\">\n          <li>Log in at <a href=\"https://epaper.business-standard.com\" target=\"_blank\" class=\"text-indigo-600 dark:text-indigo-400 font-bold underline\">epaper.business-standard.com \u2197</a></li>\n          <li>Click your <b>\ud83d\udccc Sync FinPress BS</b> bookmark on your browser toolbar.</li>\n          <li>It automatically syncs your cookies to R2 and triggers the <b>GitHub Actions workflow</b> to extract today's paper!</li>\n        </ol>\n      </div>\n\n      <!-- Optional Manual Cookie Input -->\n      <details class=\"text-xs text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-800 rounded-lg p-2.5\">\n        <summary class=\"font-bold cursor-pointer select-none text-slate-700 dark:text-slate-300 font-mono\">Manual Session Cookie Paste / Direct Submit</summary>\n        <div class=\"mt-2.5 space-y-2\">\n          <textarea id=\"bs-cookie-input\" rows=\"2\" placeholder=\"Paste document.cookie or session JSON here...\" class=\"w-full text-xs font-mono p-2 rounded bg-slate-100 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 text-slate-900 dark:text-slate-100 focus:outline-none focus:border-amber-500\"></textarea>\n          <div class=\"flex items-center gap-2\">\n            <button onclick=\"submitManualBsCookie()\" class=\"px-3 py-1.5 rounded bg-indigo-600 hover:bg-indigo-700 text-white font-mono font-bold text-xs shadow-xs\">Submit & Trigger GA</button>\n            <span id=\"bs-manual-status\" class=\"text-xs font-mono font-bold\"></span>\n          </div>\n        </div>\n      </details>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono\">\n        <a href=\"https://github.com/vedarthain/FinPress/actions/workflows/2_fetch_business_standard.yml\" target=\"_blank\" class=\"text-indigo-600 dark:text-indigo-400 hover:underline flex items-center gap-1 font-bold\">\n          <span>\u26a1 View GitHub Actions Run</span> <span>\u2197</span>\n        </a>\n        <button onclick=\"closeBsSyncModal()\" class=\"px-4 py-1.5 bg-slate-200 hover:bg-slate-300 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-900 dark:text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n\n    <!-- ================= CLIENT JAVASCRIPT ================= -->\n  <script>\n    let rawReport = null;\n    let stories = [];\n    let ipoList = [];\n    let currentView = \"feed\";\n    let selectedFeedCategory = \"ANCHOR\";\n    let selectedFeedSentiment = \"ALL\";\n    let activeStockFilter = null;\n    let activeSectorFilter = null;\n    let selectedStoryIndex = 0;\n    let currentFeedPage = 1;\n    const FEED_PAGE_SIZE = 12;\n    let currentIpoFilter = \"ALL\";\n    let currentSearchQuery = \"\";\n    let availableDates = [];\n    let currentDateIndex = 0;\n    let activeIpoMode = \"tracker\"; // 'tracker' or 'listed'\n    let activeIpoCategory = \"ALL\";  // 'ALL', 'MAINBOARD', 'SME'\n    let ipoSearchQuery = \"\";\n    let isCutoutExpanded = false;\n\n    // Benchmark dataset for 'Already Listed' IPOs\n    const benchmarkListedIpos = [\n      { id: 1, name: \"Premier Energies Ltd\", ticker: \"PREMIERENE\", date: \"03 Sep 2026\", issuePrice: 450, listPrice: 991, cmp: 1120, exchange: \"NSE / BSE Mainboard\" },\n      { id: 2, name: \"Bajaj Housing Finance Ltd\", ticker: \"BAJAJHFL\", date: \"16 Sep 2026\", issuePrice: 70, listPrice: 150, cmp: 142, exchange: \"NSE / BSE Mainboard\" },\n      { id: 3, name: \"KRN Heat Exchanger Ltd\", ticker: \"KRNHEAT\", date: \"24 Sep 2026\", issuePrice: 220, listPrice: 480, cmp: 512, exchange: \"NSE / BSE Mainboard\" },\n      { id: 4, name: \"Swiggy Ltd\", ticker: \"SWIGGY\", date: \"18 Sep 2026\", issuePrice: 390, listPrice: 420, cmp: 468, exchange: \"NSE / BSE Mainboard\" },\n      { id: 5, name: \"Diffusion Engineers Ltd\", ticker: \"DIFFUSION\", date: \"26 Sep 2026\", issuePrice: 168, listPrice: 195, cmp: 210, exchange: \"NSE / BSE Mainboard\" },\n      { id: 6, name: \"Manba Finance Ltd\", ticker: \"MANBA\", date: \"23 Sep 2026\", issuePrice: 120, listPrice: 150, cmp: 144, exchange: \"NSE / BSE Mainboard\" },\n      { id: 7, name: \"Arkade Developers Ltd\", ticker: \"ARKADE\", date: \"20 Sep 2026\", issuePrice: 128, listPrice: 175, cmp: 168, exchange: \"NSE / BSE Mainboard\" },\n      { id: 8, name: \"Western Carriers India Ltd\", ticker: \"WESTERN\", date: \"21 Sep 2026\", issuePrice: 172, listPrice: 170, cmp: 158, exchange: \"NSE / BSE Mainboard\" },\n      { id: 9, name: \"Northern Arc Capital Ltd\", ticker: \"NORTHARC\", date: \"19 Sep 2026\", issuePrice: 263, listPrice: 351, cmp: 325, exchange: \"NSE / BSE Mainboard\" }\n    ];\n\nconst allowedSections = [\n      \"ALL\", \"Sector\", \"Economy\", \"Policy\", \"Market\", \"Trade\", \"International News\", \"Others\"\n    ];\n\n    const stockDictionary = [\n      \"RELIANCE\", \"TCS\", \"INFOSYS\", \"INFY\", \"HDFC BANK\", \"HDFCBANK\", \"ICICI BANK\", \"ICICIBANK\", \"SBI\", \"SBIN\",\n      \"BHARTI AIRTEL\", \"AIRTEL\", \"ITC\", \"KOTAK BANK\", \"L&T\", \"LT\", \"TATA MOTORS\", \"TATA STEEL\", \"TATA SONS\", \"TATA TRUSTS\",\n      \"MARUTI\", \"SUN PHARMA\", \"TITAN\", \"BAJAJ FINANCE\", \"ADANI\", \"NTPC\", \"ONGC\", \"POWERGRID\", \"JSW STEEL\", \"COAL INDIA\",\n      \"COALINDIA\", \"SAIL\", \"BCCL\", \"NCL\", \"HINDALCO\", \"WIPRO\", \"TECH MAHINDRA\", \"ZOMATO\", \"PAYTM\", \"SWIGGY\",\n      \"OLA ELECTRIC\", \"OLA ELEC\", \"HAL\", \"BEL\", \"BHEL\", \"BDL\", \"IRFC\", \"RVNL\", \"IREDA\", \"VEDANTA\", \"DLF\", \"GODREJ\",\n      \"AXIS BANK\", \"ASIAN PAINTS\", \"ULTRATECH\", \"HERO MOTOCORP\", \"BAJAJ AUTO\", \"EICHER\", \"DR REDDY\", \"CIPLA\", \"TRENT\",\n      \"DMART\", \"POLYCAB\", \"DIXON\", \"BSE\", \"MCX\", \"CDSL\", \"AIR INDIA\", \"COFORGE\", \"V-GUARD\", \"HCLTECH\", \"AROVIA\",\n      \"EDELWEISS\", \"NATCO PHARMA\", \"GUJARAT THEMIS\", \"ORACLE\", \"NATRAJ ENERGY\", \"ESDS SOFTWARE\", \"INDO-MIM\", \"SAGARMALA\",\n      \"ALIBABA\", \"BYTEDANCE\", \"NVIDIA\", \"JIO\", \"NAYARA\", \"FIRESIDE\", \"META\", \"MONGODB\"\n    ];\n\n    const sectorDictionary = [\n      \"ENERGY\", \"POWER\", \"IT\", \"TECH\", \"REAL ESTATE\", \"REALTY\", \"BANKING\", \"FINANCE\", \"AUTO\", \"AUTOMOTIVE\", \"EV\",\n      \"PHARMA\", \"HEALTHCARE\", \"DEFENCE\", \"METALS\", \"STEEL\", \"MINING\", \"TELECOM\", \"FMCG\", \"CONSUMER\", \"INFRASTRUCTURE\",\n      \"INFRA\", \"AVIATION\", \"LOGISTICS\", \"CHEMICALS\", \"TEXTILES\", \"AGRICULTURE\", \"INSURANCE\", \"MEDIA\", \"RETAIL\"\n    ];\n\n    \n    let isSidebarVisible = localStorage.getItem('finpress_sidebar_visible') !== 'false';\n\n    function toggleSidebar() {\n      isSidebarVisible = !isSidebarVisible;\n      localStorage.setItem('finpress_sidebar_visible', isSidebarVisible);\n      applySidebarVisibility();\n    }\n\n    function applySidebarVisibility() {\n      const aside = document.getElementById(\"view-feed-aside\");\n      const grid = document.getElementById(\"workspace-grid\");\n      const pill = document.getElementById(\"sidebar-vertical-pill\");\n      const openBtn = document.getElementById(\"feed-open-sidebar-btn\");\n      if (!aside) return;\n\n      if (isSidebarVisible) {\n        aside.classList.remove(\"hidden\");\n        if (grid) grid.classList.remove(\"sidebar-collapsed\");\n        if (pill) pill.classList.add(\"hidden\");\n        if (openBtn) {\n          openBtn.classList.add(\"hidden\");\n          openBtn.classList.remove(\"flex\");\n        }\n      } else {\n        aside.classList.add(\"hidden\");\n        if (grid) grid.classList.add(\"sidebar-collapsed\");\n        if (pill) pill.classList.remove(\"hidden\");\n        if (openBtn) {\n          openBtn.classList.remove(\"hidden\");\n          openBtn.classList.add(\"flex\");\n        }\n      }\n    }\n\n    let isCol1Collapsed = localStorage.getItem('finpress_col1_collapsed') === 'true';\n\n    function toggleCol1() {\n      isCol1Collapsed = !isCol1Collapsed;\n      localStorage.setItem('finpress_col1_collapsed', isCol1Collapsed);\n      applyCol1Visibility();\n    }\n\n    function applyCol1Visibility() {\n      const col1 = document.getElementById(\"col-news-wire\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const openBtn = document.getElementById(\"feed-open-col1-btn\");\n      \n      if (isCol1Collapsed) {\n        if (col1) col1.classList.add(\"hidden\");\n        if (viewFeed) viewFeed.classList.add(\"feed-col1-collapsed\");\n        if (openBtn) {\n          openBtn.classList.remove(\"hidden\");\n          openBtn.classList.add(\"flex\");\n        }\n      } else {\n        if (col1) col1.classList.remove(\"hidden\");\n        if (viewFeed) viewFeed.classList.remove(\"feed-col1-collapsed\");\n        if (openBtn) {\n          openBtn.classList.add(\"hidden\");\n          openBtn.classList.remove(\"flex\");\n        }\n      }\n    }\n\n    function initTheme() {\n      const t = localStorage.getItem('finbrief_theme') || 'light';\n      applyTheme(t);\n    }\n    function toggleTheme() {\n      const isDark = document.documentElement.classList.contains('dark');\n      const next = isDark ? 'light' : 'dark';\n      applyTheme(next);\n      localStorage.setItem('finbrief_theme', next);\n    }\n    function applyTheme(t) {\n      const icon = document.getElementById('theme-icon');\n      if (t === 'dark') {\n        document.documentElement.classList.add('dark');\n        if (icon) icon.textContent = '\u2600\ufe0f';\n      } else {\n        document.documentElement.classList.remove('dark');\n        if (icon) icon.textContent = '\ud83c\udf19';\n      }\n    }\n\n    let currentFontScale = 100;\n    function initFontSize() {\n      const saved = localStorage.getItem('finpress_font_scale');\n      if (saved) {\n        currentFontScale = parseInt(saved, 10) || 100;\n      }\n      applyFontSize(currentFontScale);\n    }\n    function adjustFontSize(delta) {\n      currentFontScale = Math.min(130, Math.max(85, currentFontScale + (delta * 5)));\n      localStorage.setItem('finpress_font_scale', currentFontScale);\n      applyFontSize(currentFontScale);\n    }\n    function applyFontSize(scale) {\n      const label = document.getElementById(\"font-size-label\");\n      if (label) label.textContent = `${scale}%`;\n      document.body.style.zoom = `${scale}%`;\n      document.documentElement.style.fontSize = `${(scale / 100) * 100}%`;\n    }\n\n    let currentLayoutMode = \"split\";\n\n    function setViewMode(mode) {\n      currentLayoutMode = mode;\n      const splitBtn = document.getElementById(\"mode-split-btn\");\n      const matrixBtn = document.getElementById(\"mode-matrix-btn\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const viewMatrix = document.getElementById(\"view-matrix\");\n\n      if (splitBtn) splitBtn.className = mode === \"split\" ? \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" : \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n      if (matrixBtn) matrixBtn.className = mode === \"matrix\" ? \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" : \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n\n      if (currentView === \"ipo\") return;\n\n      if (mode === \"split\") {\n        viewFeed.classList.remove(\"hidden\");\n        viewFeed.classList.add(\"grid\");\n        viewMatrix.classList.add(\"hidden\");\n        viewMatrix.classList.remove(\"flex\");\n        renderFeedList();\n      } else {\n        viewFeed.classList.add(\"hidden\");\n        viewFeed.classList.remove(\"grid\");\n        viewMatrix.classList.remove(\"hidden\");\n        viewMatrix.classList.add(\"flex\");\n        renderMatrixTable();\n      }\n    }\n\n    function switchView(viewName) {\n      currentView = viewName;\n      const tabAnchor = document.getElementById(\"tab-btn-anchor\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const viewIpo = document.getElementById(\"view-ipo\");\n      const corpBanner = document.getElementById(\"corporate-subtabs-banner\");\n      const ipoBanner = document.getElementById(\"ipo-subtabs-banner\");\n      const deskSelect = document.getElementById(\"desk-select\");\n      const categorySelect = document.getElementById(\"category-select\");\n      const topIpoBtn = document.getElementById(\"top-ipo-hub-btn\");\n\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n\n      if (viewName === \"ipo\" || viewName === \"ipo_hub\") {\n        if (topIpoBtn) {\n          topIpoBtn.className = \"px-3 py-1 rounded-lg bg-amber-600 text-white font-mono text-[12px] font-bold flex items-center gap-1.5 shadow-md transition-transform active:scale-95 cursor-pointer ring-2 ring-amber-400\";\n          topIpoBtn.innerHTML = \"<span>\ud83d\udcf0</span> <span>Back to News</span>\";\n        }\n        if (viewFeed) viewFeed.classList.add(\"hidden\");\n        if (viewIpo) viewIpo.classList.remove(\"hidden\");\n        setIpoViewMode(activeIpoMode || 'tracker');\n        renderCategoriesAndStocksSidebar();\n        return;\n      }\n\n      if (topIpoBtn) {\n        topIpoBtn.className = \"px-3 py-1 rounded-lg bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white font-mono text-[12px] font-bold flex items-center gap-1.5 shadow-md transition-transform active:scale-95 cursor-pointer\";\n        topIpoBtn.innerHTML = \"<span>\ud83d\ude80</span> <span>IPO Hub</span>\";\n      }\n\n      if (viewIpo) viewIpo.classList.add(\"hidden\");\n      if (viewFeed) viewFeed.classList.remove(\"hidden\");\n\n      if (viewName === \"feed\") {\n        selectedFeedCategory = \"ANCHOR\";\n        if (categorySelect) categorySelect.value = \"ANCHOR\";\n        if (deskSelect) deskSelect.value = \"\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      } else if (viewName === \"anchor\") {\n        if (tabAnchor) tabAnchor.className = \"px-2.5 py-1 rounded-md transition-all bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs flex items-center gap-1.5 font-semibold\";\n        selectedFeedCategory = \"ANCHOR\";\n        if (deskSelect) deskSelect.value = \"\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      } else if (viewName === \"corporate\") {\n        if (deskSelect) deskSelect.value = \"corporate\";\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n        if (corpBanner) {\n          corpBanner.classList.remove(\"hidden\");\n          corpBanner.classList.add(\"flex\");\n          selectCorporateSub(\"ALL\");\n          return;\n        }\n      } else if (viewName === \"opinions\") {\n        if (deskSelect) deskSelect.value = \"opinions\";\n        selectedFeedCategory = \"OPINIONS\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      }\n\n      renderCategoriesAndStocksSidebar();\n      renderFeedList();\n    }\n\n    function onDeskSelect(val) {\n      if (!val) return;\n      if (val === \"ipo\") {\n        switchView(\"ipo\");\n      } else if (val === \"corporate\") {\n        switchView(\"corporate\");\n      } else if (val === \"opinions\") {\n        switchView(\"opinions\");\n      }\n    }\n\n    function selectIpoSub(sub) {\n      if (sub === 'ALL') {\n        selectedFeedCategory = \"IPO_ALL\";\n      } else if (sub === 'DRHP') {\n        selectedFeedCategory = \"IPO_DRHP\";\n      } else if (sub === 'BIDDING') {\n        selectedFeedCategory = \"IPO_BIDDING\";\n      } else if (sub === 'NOTICES') {\n        selectedFeedCategory = \"IPO_NOTICES\";\n      }\n      \n      const subLower = sub.toLowerCase();\n      [\"all\", \"drhp\", \"bidding\", \"notices\"].forEach(t => {\n        const btn = document.getElementById(`ipo-tab-${t}`);\n        if (btn) {\n          if (t === subLower) {\n            btn.className = \"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\";\n          } else {\n            btn.className = \"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\";\n          }\n        }\n      });\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      renderFeedList();\n    }\n\n    function selectCorporateSub(sub) {\n      if (sub === 'ALL') {\n        selectedFeedCategory = \"CORPORATE_ALL\";\n      } else if (sub === 'EVENTS') {\n        selectedFeedCategory = \"EVENTS\";\n      } else if (sub === 'APPOINTMENTS') {\n        selectedFeedCategory = \"APPOINTMENTS\";\n      }\n      \n      const subLower = sub === 'ALL' ? 'all' : sub === 'EVENTS' ? 'events' : 'appts';\n      [\"all\", \"events\", \"appts\"].forEach(t => {\n        const btn = document.getElementById(`corp-tab-${t}`);\n        if (btn) {\n          if (t === subLower) {\n            btn.className = \"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\";\n          } else {\n            btn.className = \"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\";\n          }\n        }\n      });\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      renderFeedList();\n    }\n\n    function onCategorySelect(val) {\n      if (currentView === \"ipo\") {\n        currentView = \"feed\";\n        const topIpoBtn = document.getElementById(\"top-ipo-hub-btn\");\n        if (topIpoBtn) {\n          topIpoBtn.className = \"px-3 py-1 rounded-lg bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white font-mono text-[12px] font-bold flex items-center gap-1.5 shadow-md transition-transform active:scale-95 cursor-pointer\";\n          topIpoBtn.innerHTML = \"<span>\ud83d\ude80</span> <span>IPO Hub</span>\";\n        }\n        const viewIpo = document.getElementById(\"view-ipo\");\n        if (viewIpo) viewIpo.classList.add(\"hidden\");\n        const viewFeed = document.getElementById(\"view-feed\");\n        if (viewFeed) viewFeed.classList.remove(\"hidden\");\n      }\n\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      selectedFeedCategory = val;\n      activeStockFilter = null;\n      activeSectorFilter = null;\n      \n      const deskSelect = document.getElementById(\"desk-select\");\n      if (deskSelect) deskSelect.value = \"\";\n      \n      const corpBanner = document.getElementById(\"corporate-subtabs-banner\");\n      if (corpBanner) corpBanner.classList.add(\"hidden\");\n      const ipoBanner = document.getElementById(\"ipo-subtabs-banner\");\n      if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      \n      const tabAnchor = document.getElementById(\"tab-btn-anchor\");\n      if (tabAnchor) tabAnchor.className = \"px-2.5 py-1 rounded-md transition-all text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 flex items-center gap-1.5 font-medium\";\n      \n      const catSelect = document.getElementById(\"category-select\");\n      if (catSelect && val !== \"ALL\" && !val.startsWith(\"IPO\") && !val.startsWith(\"CORPORATE\") && val !== \"OPINIONS\" && val !== \"ANCHOR\") {\n        catSelect.value = val;\n      } else if (catSelect && val === \"ANCHOR\") {\n        catSelect.value = \"ANCHOR\";\n      }\n\n      renderCategoriesAndStocksSidebar();\n      renderFeedList();\n    }\n\n    function isFillerHeadline(hl) {\n      const h = hl.toLowerCase();\n      return (\n        h.includes(\"special edition and general overview\") ||\n        h.includes(\"general overview\") ||\n        h.includes(\"newspaper overview\") ||\n        h.includes(\"sunday special edition\") ||\n        h.includes(\"fe sunday special\") ||\n        h.includes(\"edition overview\") ||\n        h.includes(\"e-paper index\") ||\n        h.includes(\"table of contents\")\n      );\n    }\n\n    function deriveClientCatalyst(story, brief, bullets) {\n      if (story.catalyst && story.catalyst.trim() && story.catalyst !== brief) return story.catalyst.trim();\n      const hl = story.headline || \"\";\n      const full = (hl + \" \" + brief).toLowerCase();\n      if (full.includes(\"gdp\") && (full.includes(\"growth\") || full.includes(\"finmin\"))) return \"Upward GDP nowcasting supported by resilient manufacturing gross value added.\";\n      if (full.includes(\"gst\") && full.includes(\"collection\")) return \"Robust indirect tax mop-up driven by elevated import volume collections and manufacturing demand.\";\n      if (full.includes(\"rupee\") && (full.includes(\"drop\") || full.includes(\"low\") || full.includes(\"depreciation\"))) return \"Spike in US Treasury yields and FPI capital outflows breaching psychological currency support.\";\n      if (full.includes(\"pmi\") || full.includes(\"manufacturing\")) return \"Resilient manufacturing new orders, export expansion, and accelerated factory output.\";\n      if (full.includes(\"upi\") || full.includes(\"digital payment\")) return \"Record digital transaction velocity and retail payment infrastructure volume breakthrough.\";\n      if (full.includes(\"sales\") && (full.includes(\"vehicle\") || full.includes(\"auto\") || full.includes(\"pv\"))) return \"Festive retail inventory build-up and tax rationalization boosting domestic automotive demand.\";\n      if (bullets && bullets.length > 0) {\n        const cleanB = bullets[0].replace(/[*_#]/g, '').trim();\n        if (cleanB.length < 130 && cleanB !== brief) return cleanB;\n      }\n      return `Primary event trigger: ${hl.split(':')[0]} with operational transmission.`;\n    }\n\n    function deriveClientMarketImpact(story, brief, bullets, category) {\n      if (story.market_impact && story.market_impact.trim() && story.market_impact !== brief) return story.market_impact.trim();\n      const hl = story.headline || \"\";\n      const full = (hl + \" \" + brief + \" \" + (bullets || []).join(\" \")).toLowerCase();\n      const cat = category || story.category || \"Market\";\n      \n      if (cat === \"Economy\") {\n        if (full.includes(\"gst\") || full.includes(\"tax\")) return \"Directly strengthens the Centre's fiscal deficit glide path, providing sovereign borrowing cushion and headroom for sustained capex. Import tax buoyancy reflects sustained intermediate capital goods intake by domestic manufacturers.\";\n        if (full.includes(\"rupee\") || full.includes(\"dollar\")) return \"Increases landed import costs for crude oil and key electronics, exerting near-term pressure on imported inflation, while providing a margin tailwind for export-heavy sectors (IT, Pharma) on unhedged dollar revenues.\";\n        if (full.includes(\"gdp\") || full.includes(\"pmi\")) return \"Underpins corporate revenue run-rate projections and supports capacity expansion decisions across capital goods, affirming domestic macro resilience against global fragmentation headwinds.\";\n        return \"Influences macroeconomic liquidity conditions, sovereign yield spreads, and medium-term policy rate expectations.\";\n      }\n      if (cat === \"Sector\" || cat === \"Market\") {\n        if (full.includes(\"auto\") || full.includes(\"vehicle\")) return \"Improves operating leverage and fixed-cost absorption for OEMs and Tier-1 auto-ancillary suppliers, bolstering dealer channel liquidity ahead of the festive inventory cycle.\";\n        if (full.includes(\"it\") || full.includes(\"tech\")) return \"Sequential constant-currency revenue growth remains selective; pricing realization and EBIT margin resilience become key stock catalysts amid mega-deal ramp velocity.\";\n        if (full.includes(\"metal\") || full.includes(\"steel\") || full.includes(\"mining\")) return \"Strong domestic volume growth helps insulate miners from volatile global benchmark pricing swings, ensuring uninterrupted raw material feed for downstream infrastructure fabrication.\";\n        if (full.includes(\"bank\") || full.includes(\"credit\") || full.includes(\"lending\")) return \"Sustained credit disbursement velocity supports Net Interest Income (NII) while deposit cost repricing dynamics remain the primary driver for Net Interest Margin (NIM) trajectory.\";\n        return \"Directly impacts EBITDA margin expectations, working capital requirements, and relative valuation multiples against sector benchmarks.\";\n      }\n      if (cat === \"IPO\") return \"Expands institutional free-float and offers price discovery benchmark for peer group enterprise valuations, with listing premium hinging on anchor institutional subscription quality and post-issue earnings visibility.\";\n      if (cat === \"Policy\" || cat === \"Trade\") return \"Alters compliance frameworks and tariff structures, realigning domestic supply-chain cost competitiveness while reducing regulatory friction for compliant industry participants.\";\n      if (cat === \"Corporate Events\" || cat === \"Corporate Appointments\") return \"Clarifies management execution roadmap, corporate governance posture, and capital allocation priorities for institutional investors.\";\n      return \"Ripples into relevant industry peer groups, shaping operational positioning, margin resilience, and investor sentiment across the sector.\";\n    }\n\n    function deriveClientSentimentReasoning(story, sent) {\n      if (story.sentiment_reasoning && story.sentiment_reasoning.trim() && story.sentiment_reasoning !== story.brief_details) return story.sentiment_reasoning.trim();\n      if (sent === \"BULLISH\") return \"Positive fundamental development reinforcing operational upside, strong volume/revenue execution, and supportive valuation metrics.\";\n      if (sent === \"BEARISH\") return \"Headwind creating margin compression, near-term liquidity pressure, or elevated regulatory/macro vulnerability.\";\n      return \"Balanced fundamentals with neutral transmission; market will track ongoing execution and follow-through metrics.\";\n    }\n\n    function parseStory(story, idx) {\n      if (!story || isFillerHeadline(story.headline || \"\")) return null;\n\n      const brief_details = story.brief_details || story.brief || \"\";\n      const bullet_points = Array.isArray(story.bullet_points) ? story.bullet_points : (Array.isArray(story.detailed_points) ? story.detailed_points : []);\n      const rawPage = Array.isArray(story.page_numbers) ? story.page_numbers.join(\" \") : String(story.page_numbers || \"\");\n      const sourcePaper = String(story.source_paper || \"\");\n      const pageStr = (rawPage + \" \" + sourcePaper).toLowerCase();\n      const fullText = ((story.headline || \"\") + \" \" + brief_details + \" \" + bullet_points.join(\" \")).toLowerCase();\n\n      // Source Paper Flags\n      const hasFe = pageStr.includes(\"fe\") || pageStr.includes(\"financial express\") || sourcePaper.toLowerCase().includes(\"express\");\n      const hasBs = pageStr.includes(\"bs\") || pageStr.includes(\"business standard\") || sourcePaper.toLowerCase().includes(\"standard\");\n\n      // Strict Market Section Rule: Bank disclosures/Statutory notices belong in Corporate Events\n      let category = story.category;\n      if (category === \"Market\" || category === \"Others\") {\n        const noticeTerms = [\"disclosure\", \"public notice\", \"statutory notice\", \"possession notice\", \"postal ballot\", \"e-voting\", \"annual general meeting\", \"agm notice\", \"egm notice\", \"co-op bank\", \"co-operative bank\", \"financial and regulatory disclosure\", \"auction notice\"];\n        if (noticeTerms.some(t => fullText.includes(t))) {\n          category = \"Corporate Events\";\n        }\n      }\n\n      // Detect Opinions / Editorial\n      const isOpinion = category === \"Opinions\" || category === \"Opinion\" || category === \"Editorial\" || fullText.includes(\"opinion:\") || fullText.includes(\"editorial:\");\n      const isFrontPage = pageStr.includes(\"page 1\") || pageStr.includes(\"p1\") || pageStr.includes(\"page1\") || pageStr.includes(\"anchor\") || story.is_front_page;\n\n      // Dynamic Stock & Sector Detection\n      const detectedStocks = [];\n      const detectedSectors = [];\n      const upperText = ((story.headline || \"\") + \" \" + brief_details + \" \" + bullet_points.join(\" \")).toUpperCase();\n\n      if (typeof stockDictionary !== \"undefined\") {\n        stockDictionary.forEach(stk => {\n          if (new RegExp(`\\\\b${stk.replace('&', '\\\\&')}\\\\b`, 'i').test(upperText)) {\n            detectedStocks.push(stk);\n          }\n        });\n      }\n\n      if (typeof sectorDictionary !== \"undefined\") {\n        sectorDictionary.forEach(sec => {\n          if (new RegExp(`\\\\b${sec.replace('&', '\\\\&')}\\\\b`, 'i').test(upperText)) {\n            detectedSectors.push(sec);\n          }\n        });\n      }\n\n      let ipoData = null;\n      if (category === \"IPO\") {\n        ipoData = parseIpoItem(story, idx);\n      }\n\n      const uniqueStocks = (story.stocks && story.stocks.length > 0) ? story.stocks : [...new Set(detectedStocks)].slice(0, 4);\n      const uniqueSectors = (story.sectors && story.sectors.length > 0) ? story.sectors : [...new Set(detectedSectors)].slice(0, 3);\n      const allTickers = (story.tickers && story.tickers.length > 0) ? story.tickers : [...new Set([...uniqueStocks, ...uniqueSectors])].slice(0, 5);\n\n      const sentiment = (story.sentiment || \"NEUTRAL\").toUpperCase();\n      const catalyst = deriveClientCatalyst(story, brief_details, bullet_points);\n      const marketImpact = deriveClientMarketImpact(story, brief_details, bullet_points, category);\n      const sentimentReasoning = deriveClientSentimentReasoning(story, sentiment);\n\n      return {\n        id: story.id || (idx + 1),\n        headline: story.headline || \"Untitled Intelligence Item\",\n        category: category || \"Market\",\n        sentiment: sentiment,\n        sentimentReasoning: sentimentReasoning,\n        catalyst: catalyst,\n        market_impact: marketImpact,\n        tickers: allTickers,\n        stocks: uniqueStocks,\n        sectors: uniqueSectors,\n        page_numbers: story.page_numbers || (hasFe ? \"FE (Page 1)\" : \"BS (Page 1)\"),\n        source_paper: story.source_paper || (hasFe ? \"Financial Express\" : hasBs ? \"Business Standard\" : \"Financial Express\"),\n        brief_details: brief_details,\n        bullet_points: bullet_points,\n        isFrontPage: isFrontPage,\n        hasFe: hasFe || (!hasBs),\n        hasBs: hasBs,\n        isOpinion: isOpinion,\n        ipoTag: ipoData ? ipoData.filterTag : null,\n        ipoData: ipoData\n      };\n    }\n\n    function parseIpoItem(s, idx) {\n      const h = s.headline;\n      const d = s.brief_details;\n      const combined = (h + \" \" + d).toLowerCase();\n\n      let company = h.replace(/public announcement|basis of allotment|files ipo papers|files draft ipo papers|ipo subscribed|files for|shelves|amid market uncertainty/gi, '').trim();\n      company = company.replace(/^(biscuit maker|nine firms filing ipo papers with sebi:|after reverse flip to india: cfo)/gi, '').trim();\n      if (company.length > 32) company = company.slice(0, 32) + '...';\n\n      let size = \"Not Disclosed\";\n      const sizeMatch = (h + \" \" + d).match(/(?:\u20b9|\u2090|rs\\.?)\\s?([\\d,]+(?:\\.\\d+)?)\\s?(?:cr|crore|lakh)/i);\n      if (sizeMatch) size = `\u20b9${sizeMatch[1]} Cr`;\n      else if (combined.includes(\"fresh issue\")) size = \"Fresh Issue\";\n      else if (combined.includes(\"sme\")) size = \"SME Issue\";\n\n      // Detect Target Listing Exchange\n      let exchange = \"NSE / BSE Mainboard\";\n      if (combined.includes(\"sme\") || combined.includes(\"emerge\")) {\n        exchange = \"NSE Emerge / BSE SME\";\n      } else if (combined.includes(\"bse only\") || combined.includes(\"bse startup\")) {\n        exchange = \"BSE Only\";\n      }\n\n      let stage = \"\ud83d\udccb DRHP Filed\";\n      let stageBadge = \"bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/40 dark:text-amber-300\";\n      let filterTag = \"DRHP\";\n\n      if (combined.includes(\"subscribed\")) {\n        stage = \"\ud83d\udcc8 Active Bidding\";\n        stageBadge = \"bg-emerald-50 text-emerald-800 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-300\";\n        filterTag = \"BIDDING\";\n      } else if (combined.includes(\"allotment\") || combined.includes(\"basis\")) {\n        stage = \"\ud83c\udfdb\ufe0f Allotment Out\";\n        stageBadge = \"bg-blue-50 text-blue-800 border-blue-200 dark:bg-blue-950/40 dark:text-blue-300\";\n        filterTag = \"NOTICES\";\n      } else if (combined.includes(\"shelve\") || combined.includes(\"delay\")) {\n        stage = \"\u23f8\ufe0f Deferred\";\n        stageBadge = \"bg-rose-50 text-rose-800 border-rose-200 dark:bg-rose-950/40 dark:text-rose-300\";\n        filterTag = \"DRHP\";\n      } else if (combined.includes(\"announcement\") || combined.includes(\"notice\")) {\n        stage = \"\ud83d\udce2 Public Issue Notice\";\n        stageBadge = \"bg-purple-50 text-purple-800 border-purple-200 dark:bg-purple-950/40 dark:text-purple-300\";\n        filterTag = \"NOTICES\";\n      }\n\n      let demand = \"Filing Stage\";\n      const subMatch = (h + \" \" + d).match(/subscribed\\s+([\\d\\.]+)\\s+(?:times|x)/i);\n      const subPctMatch = (h + \" \" + d).match(/subscribed\\s+([\\d\\.]+%)/i);\n      if (subMatch) demand = `${subMatch[1]}x Subscribed`;\n      else if (subPctMatch) demand = `${subPctMatch[1]} Subscribed`;\n      else if (stage.includes(\"Allotment\")) demand = \"Completed\";\n\n      return {\n        id: idx + 1,\n        headline: h,\n        company: company || h.slice(0, 25),\n        size,\n        exchange,\n        stage,\n        stageBadge,\n        filterTag,\n        demand,\n        details: d,\n        source: s.page_numbers || \"FE / BS\"\n      };\n    }\n\n    async function fetchDates() {\n      try {\n        const res = await fetch(`/api/dates?t=${Date.now()}`);\n        if (res.ok) {\n          availableDates = await res.json();\n          if (availableDates && availableDates.length > 0) {\n            const picker = document.getElementById(\"calendar-picker\");\n            if (rawReport && rawReport.edition_date) {\n              if (picker) picker.value = rawReport.edition_date;\n            } else if (picker) {\n              picker.value = availableDates[0];\n            }\n          }\n        }\n      } catch (e) {}\n    }\n\n    function navigateDate(dir) {\n      if (!availableDates || availableDates.length === 0) return;\n      currentDateIndex += dir;\n      if (currentDateIndex < 0) currentDateIndex = 0;\n      if (currentDateIndex >= availableDates.length) currentDateIndex = availableDates.length - 1;\n      const target = availableDates[currentDateIndex];\n      const picker = document.getElementById(\"calendar-picker\");\n      if (picker) picker.value = target;\n      loadData(target);\n    }\n\n    function onCalendarSelect(val) {\n      if (!val) return;\n      if (availableDates.includes(val)) {\n        currentDateIndex = availableDates.indexOf(val);\n      }\n      loadData(val);\n    }\n\n    async function onDateChange(selectedDate) {\n      const picker = document.getElementById(\"calendar-picker\");\n      if (picker) picker.value = selectedDate;\n      await loadData(selectedDate);\n    }\n\n    async function loadData(targetDate = null) {\n      try {\n        const endpoint = targetDate ? `/api/report?date=${targetDate}&t=${Date.now()}` : `/api/report?t=${Date.now()}`;\n        const res = await fetch(endpoint);\n        if (!res.ok) throw new Error(\"Failed\");\n        rawReport = await res.json();\n      } catch (e) {\n        try {\n          const fallbackUrl = targetDate \n            ? `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/news_report_unified_${targetDate}.json?t=${Date.now()}`\n            : `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/news_report_unified_latest.json?t=${Date.now()}`;\n          const res = await fetch(fallbackUrl);\n          rawReport = await res.json();\n        } catch (err) {}\n      }\n\n      if (rawReport && rawReport.major_stories) {\n        const edDate = rawReport.edition_date;\n        const dateInput = document.getElementById(\"calendar-picker\");\n        if (dateInput && edDate) dateInput.value = edDate;\n        if (availableDates.includes(edDate)) {\n          currentDateIndex = availableDates.indexOf(edDate);\n        }\n\n        stories = rawReport.major_stories\n          .map((s, idx) => parseStory(s, idx))\n          .filter(Boolean);\n\n        const rawIpos = stories.filter(s => s.category === \"IPO\");\n        ipoList = rawIpos.map((s, idx) => s.ipoData || parseIpoItem(s, idx));\n        restoreNavigationState();\n        initMetrics();\n        applySidebarVisibility();\n        applyCol1Visibility();\n        if (currentView === \"ipo\") {\n          renderIpoTable();\n        } else if (currentView === \"corporate\") {\n          renderCorporateDeskTable();\n        } else {\n          renderFeedList();\n        }\n      }\n    }\n\n    function saveNavigationState() {\n      try {\n        const state = {\n          view: currentView,\n          category: selectedFeedCategory,\n          page: currentFeedPage,\n          storyIndex: selectedStoryIndex,\n          stock: activeStockFilter,\n          sector: activeSectorFilter,\n          sentiment: selectedFeedSentiment,\n          layout: currentLayoutMode,\n          date: rawReport?.edition_date\n        };\n        sessionStorage.setItem(\"finpress_nav_state\", JSON.stringify(state));\n        \n        // Update URL search parameters without page reload (for sharing & refresh retention)\n        const url = new URL(window.location);\n        url.searchParams.set(\"cat\", selectedFeedCategory);\n        url.searchParams.set(\"page\", currentFeedPage);\n        url.searchParams.set(\"story\", selectedStoryIndex);\n        if (currentView !== \"feed\") url.searchParams.set(\"view\", currentView);\n        else url.searchParams.delete(\"view\");\n        history.replaceState(state, \"\", url.toString());\n      } catch(e) {}\n    }\n\n    function restoreNavigationState() {\n      try {\n        const url = new URL(window.location);\n        const saved = JSON.parse(sessionStorage.getItem(\"finpress_nav_state\") || \"{}\");\n        \n        const cat = url.searchParams.get(\"cat\") || saved.category;\n        const page = parseInt(url.searchParams.get(\"page\") || saved.page, 10);\n        const story = parseInt(url.searchParams.get(\"story\") || saved.storyIndex, 10);\n        const view = url.searchParams.get(\"view\") || saved.view;\n\n        if (cat) selectedFeedCategory = cat;\n        if (!isNaN(page) && page >= 1) currentFeedPage = page;\n        if (!isNaN(story) && story >= 0) selectedStoryIndex = story;\n        if (view) currentView = view;\n        if (saved.stock) activeStockFilter = saved.stock;\n        if (saved.sector) activeSectorFilter = saved.sector;\n        if (saved.sentiment) selectedFeedSentiment = saved.sentiment;\n        if (saved.layout) currentLayoutMode = saved.layout;\n      } catch(e) {}\n    }\n\n    function updateDropdownOptions(coreCount, ipoCount, corpCount, opCount) {\n      const catSelect = document.getElementById(\"category-select\");\n      if (catSelect) {\n        const counts = {\n          Sector: stories.filter(s => s.category === \"Sector\" && !s.isOpinion).length,\n          Economy: stories.filter(s => s.category === \"Economy\" && !s.isOpinion).length,\n          Policy: stories.filter(s => s.category === \"Policy\" && !s.isOpinion).length,\n          Market: stories.filter(s => s.category === \"Market\" && !s.isOpinion).length,\n          Trade: stories.filter(s => s.category === \"Trade\" && !s.isOpinion).length,\n          \"International News\": stories.filter(s => s.category === \"International News\" && !s.isOpinion).length,\n          Others: stories.filter(s => s.category === \"Others\" && !s.isOpinion).length\n        };\n        catSelect.innerHTML = `\n          <option value=\"ALL\">\u26a1 All Stories (${stories.length})</option>\n          <option value=\"Sector\">Sector (${counts.Sector})</option>\n          <option value=\"Economy\">Economy (${counts.Economy})</option>\n          <option value=\"Policy\">Policy (${counts.Policy})</option>\n          <option value=\"Market\">Market (${counts.Market})</option>\n          <option value=\"Trade\">Trade & FX (${counts.Trade})</option>\n          <option value=\"International News\">International (${counts[\"International News\"]})</option>\n          <option value=\"Others\">General Features (${counts.Others})</option>\n        `;\n        if (selectedFeedCategory !== \"ANCHOR\" && !selectedFeedCategory.startsWith(\"CORPORATE\") && !selectedFeedCategory.startsWith(\"IPO\") && selectedFeedCategory !== \"OPINIONS\") {\n          catSelect.value = selectedFeedCategory;\n        } else {\n          catSelect.value = \"ALL\";\n        }\n      }\n\n      const deskSelect = document.getElementById(\"desk-select\");\n      if (deskSelect) {\n        deskSelect.innerHTML = `\n          <option value=\"\" disabled ${currentView === 'feed' && selectedFeedCategory !== 'OPINIONS' && !selectedFeedCategory.startsWith('CORPORATE') && !selectedFeedCategory.startsWith('IPO') ? 'selected' : ''}>\ud83c\udfdb\ufe0f Specialized Desks \u25be</option>\n          <option value=\"ipo\" ${currentView === 'ipo' || selectedFeedCategory.startsWith('IPO') ? 'selected' : ''}>\ud83d\ude80 IPO Central (${ipoCount})</option>\n          <option value=\"corporate\" ${currentView === 'corporate' || selectedFeedCategory.startsWith('CORPORATE') ? 'selected' : ''}>\ud83c\udfe2 Corporate (${corpCount})</option>\n          <option value=\"opinions\" ${selectedFeedCategory === 'OPINIONS' ? 'selected' : ''}>\u270d\ufe0f Opinions (${opCount})</option>\n        `;\n      }\n    }\n\n    function initMetrics() {\n      // Core All News strictly excludes IPO, Corporate Events, Corporate Appointments, and Opinions\n      const coreStories = stories.filter(s => s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion);\n      const totalIpos = ipoList.length;\n      const anchorCount = coreStories.filter(s => s.isFrontPage).length;\n      const corpEventsCount = stories.filter(s => s.category === \"Corporate Events\").length;\n      const corpApptsCount = stories.filter(s => s.category === \"Corporate Appointments\").length;\n      const corpCount = corpEventsCount + corpApptsCount;\n      const opinionsCount = stories.filter(s => s.isOpinion).length;\n\n      const drhpCount = ipoList.filter(i => (i.stage || \"\").includes(\"DRHP\") || (i.filterTag || \"\") === \"DRHP\").length;\n      const biddingCount = ipoList.filter(i => (i.stage || \"\").includes(\"Bidding\") || (i.stage || \"\").includes(\"Open\") || (i.filterTag || \"\") === \"BIDDING\").length;\n      const noticesCount = totalIpos - drhpCount - biddingCount;\n\n      const topTotal = document.getElementById(\"top-total-count\");\n      if (topTotal) topTotal.textContent = stories.length;\n      const tabAnchor = document.getElementById(\"tab-anchor-count\");\n      if (tabAnchor) tabAnchor.textContent = anchorCount;\n\n      // Update IPO Sub-tab counts\n      const ipoSubAll = document.getElementById(\"ipo-sub-all-count\");\n      if (ipoSubAll) ipoSubAll.textContent = totalIpos;\n      const ipoSubDrhp = document.getElementById(\"ipo-sub-drhp-count\");\n      if (ipoSubDrhp) ipoSubDrhp.textContent = drhpCount;\n      const ipoSubBidding = document.getElementById(\"ipo-sub-bidding-count\");\n      if (ipoSubBidding) ipoSubBidding.textContent = biddingCount;\n      const ipoSubNotices = document.getElementById(\"ipo-sub-notices-count\");\n      if (ipoSubNotices) ipoSubNotices.textContent = noticesCount;\n\n      // Update Corporate Sub-tab counts\n      const corpSubAll = document.getElementById(\"corp-sub-all-count\");\n      if (corpSubAll) corpSubAll.textContent = corpCount;\n      const corpSubEvents = document.getElementById(\"corp-sub-events-count\");\n      if (corpSubEvents) corpSubEvents.textContent = corpEventsCount;\n      const corpSubAppts = document.getElementById(\"corp-sub-appts-count\");\n      if (corpSubAppts) corpSubAppts.textContent = corpApptsCount;\n\n      // Update Dropdowns with Section Numbers\n      updateDropdownOptions(coreStories.length, totalIpos, corpCount, opinionsCount);\n\n      let bCount = 0, rCount = 0;\n      coreStories.forEach(s => {\n        if (s.sentiment === \"BULLISH\") bCount++;\n        else if (s.sentiment === \"BEARISH\") rCount++;\n      });\n      const feedAll = document.getElementById(\"feed-count-all\");\n      if (feedAll) feedAll.textContent = coreStories.length;\n      const feedBullish = document.getElementById(\"feed-count-bullish\");\n      if (feedBullish) feedBullish.textContent = bCount;\n      const feedBearish = document.getElementById(\"feed-count-bearish\");\n      if (feedBearish) feedBearish.textContent = rCount;\n\n      // Render Source Pipeline Health\n      const healthContainer = document.getElementById(\"source-health-container\");\n      const alertBanner = document.getElementById(\"source-alert-banner\");\n      const alertText = document.getElementById(\"source-alert-text\");\n\n      if (healthContainer) {\n        healthContainer.innerHTML = \"\";\n        const statuses = (rawReport && rawReport.source_statuses) || {};\n        \n        let hasFailure = false;\n        let failureDetails = [];\n\n        const feStatus = statuses.financial_express || \"\u2705 FE (Active)\";\n        const bsStatus = statuses.business_standard || (stories.some(s => (s.page_numbers || \"\").includes(\"BS\")) ? \"\u2705 BS (Active)\" : \"\u274c BS (Session Expired)\");\n\n        const fePill = document.createElement(\"span\");\n        fePill.className = feStatus.includes(\"\u2705\") \n          ? \"px-1.5 py-0.2 rounded bg-slate-900 border border-slate-700 text-slate-300 font-bold\" \n          : \"px-1.5 py-0.2 rounded bg-rose-500/20 border border-rose-500/40 text-rose-300 font-bold\";\n        fePill.textContent = `FE: ${feStatus.includes(\"\u2705\") ? '\u2705' : '\u274c'}`;\n        fePill.title = `Financial Express: ${feStatus}`;\n        healthContainer.appendChild(fePill);\n\n        const bsPill = document.createElement(\"button\");\n        const bsOk = bsStatus.includes(\"\u2705\") || bsStatus.includes(\"Active\");\n        bsPill.className = bsOk \n          ? \"px-1.5 py-0.2 rounded bg-slate-900 border border-slate-700 text-slate-300 font-bold hover:border-indigo-400 cursor-pointer transition-colors\" \n          : \"px-1.5 py-0.2 rounded bg-rose-500/20 border border-rose-500/40 text-rose-300 font-bold hover:bg-rose-500/30 cursor-pointer animate-pulse\";\n        bsPill.textContent = `BS: ${bsOk ? '\u2705' : '\u274c Sync'}`;\n        bsPill.title = `Business Standard: ${bsStatus} - Click to Sync Session`;\n        bsPill.onclick = (e) => { e.preventDefault(); openBsSyncModal(); };\n        healthContainer.appendChild(bsPill);\n\n        if (!bsOk) {\n          hasFailure = true;\n          failureDetails.push(`Business Standard subscriber session expired. <button onclick=\"openBsSyncModal()\" class=\"underline font-bold text-amber-300 hover:text-white ml-1\">\u26a1 Click here to 1-Click Sync & Trigger GitHub Actions</button>`);\n        }\n        if (!feStatus.includes(\"\u2705\")) {\n          hasFailure = true;\n          failureDetails.push(\"Financial Express edition failed to download.\");\n        }\n\n        if (hasFailure && alertBanner && alertText) {\n          alertText.innerHTML = `<b>Edition Notice:</b> ${failureDetails.join(\" \u00b7 \")}`;\n          alertBanner.classList.remove(\"hidden\");\n        } else if (alertBanner) {\n          alertBanner.classList.add(\"hidden\");\n        }\n      }\n\n      renderCategoriesAndStocksSidebar();\n      renderFeedList();\n    }\n\n    // ================= FILTER LOGIC =================\n    function getFilteredStories() {\n      const q = currentSearchQuery.toLowerCase().trim();\n      const terms = q.split(\" \").filter(Boolean);\n\n      return stories.filter(s => {\n        const fullContent = (s.headline + \" \" + (s.brief_details || \"\") + \" \" + (s.bullet_points || []).join(\" \") + \" \" + (s.tickers || []).join(\" \") + \" \" + (s.sectors || []).join(\" \") + \" \" + s.category).toLowerCase();\n        const matchQuery = terms.length === 0 || terms.every(t => fullContent.includes(t));\n\n        // When Sector filter is selected: show ONLY news in that selected sector\n        if (activeSectorFilter) {\n          const matchSector = (s.sectors && s.sectors.includes(activeSectorFilter)) || (s.category && s.category.toUpperCase().includes(activeSectorFilter.toUpperCase())) || ((s.headline + \" \" + (s.brief_details || \"\")).toUpperCase().includes(activeSectorFilter.toUpperCase()));\n          return matchSector && matchQuery;\n        }\n\n        // When Stock filter is selected: show ONLY news in that selected stock\n        if (activeStockFilter) {\n          const matchStock = (s.stocks && s.stocks.includes(activeStockFilter)) || (s.tickers && s.tickers.includes(activeStockFilter)) || ((s.headline + \" \" + (s.brief_details || \"\")).toUpperCase().includes(activeStockFilter.toUpperCase()));\n          return matchStock && matchQuery;\n        }\n\n        let matchSec = true;\n        if (selectedFeedCategory === \"ALL\") {\n          matchSec = true;\n        } else if (selectedFeedCategory === \"SOURCE_FE\") {\n          matchSec = s.hasFe;\n        } else if (selectedFeedCategory === \"SOURCE_BS\") {\n          matchSec = s.hasBs;\n        } else if (selectedFeedCategory === \"ANCHOR\") {\n          matchSec = s.isFrontPage;\n        } else if (selectedFeedCategory === \"IPO_ALL\") {\n          matchSec = s.category === \"IPO\";\n        } else if (selectedFeedCategory === \"CORPORATE_ALL\") {\n          matchSec = s.category === \"Corporate Events\" || s.category === \"Corporate Appointments\";\n        } else if (selectedFeedCategory === \"EVENTS\") {\n          matchSec = s.category === \"Corporate Events\";\n        } else if (selectedFeedCategory === \"APPOINTMENTS\") {\n          matchSec = s.category === \"Corporate Appointments\";\n        } else if (selectedFeedCategory === \"OPINIONS\") {\n          matchSec = s.isOpinion;\n        } else if (selectedFeedCategory === \"Others\") {\n          matchSec = s.category === \"Others\";\n        } else {\n          matchSec = s.category === selectedFeedCategory;\n        }\n\n        const matchSent = selectedFeedSentiment === \"ALL\" || s.sentiment === selectedFeedSentiment;\n\n        return matchSec && matchSent && matchQuery;\n      });\n    }\n\n    function navigateStory(dir) {\n      const displayed = getFilteredStories();\n      const total = displayed.length;\n      if (total === 0) return;\n      selectedStoryIndex += dir;\n      if (selectedStoryIndex < 0) selectedStoryIndex = 0;\n      if (selectedStoryIndex >= total) selectedStoryIndex = total - 1;\n      currentFeedPage = Math.floor(selectedStoryIndex / FEED_PAGE_SIZE) + 1;\n      renderFeedList();\n    }\n\n    function changeFeedPage(delta) {\n      const displayed = getFilteredStories();\n      const totalPages = Math.ceil(displayed.length / FEED_PAGE_SIZE) || 1;\n      const targetPage = currentFeedPage + delta;\n      if (targetPage >= 1 && targetPage <= totalPages) {\n        currentFeedPage = targetPage;\n        selectedStoryIndex = (currentFeedPage - 1) * FEED_PAGE_SIZE;\n        renderFeedList();\n      }\n    }\n\n    // ================= SEARCH HANDLING =================\n    function onSearchInput() {\n      const val = document.getElementById(\"global-search\").value.trim();\n      currentSearchQuery = val;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-search-btn\").classList.toggle(\"hidden\", val.length === 0);\n      \n      if (currentView === \"ipo\") {\n        renderIpoTable();\n      } else if (currentLayoutMode === \"split\") {\n        renderFeedList();\n      } else {\n        renderMatrixTable();\n      }\n    }\n\n    function clearSearch() {\n      document.getElementById(\"global-search\").value = \"\";\n      currentSearchQuery = \"\";\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-search-btn\").classList.add(\"hidden\");\n      if (currentView === \"ipo\") renderIpoTable();\n      else if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    // ================= SQUEEZED TREE-VIEW SIDEBAR WITH COLOR-CODED CLUSTERED STOCKS =================\n    let treeState = {\n      categories: true,  // Open by default\n      sectors: false,    // Collapsed by default\n      stocks: false      // Collapsed by default\n    };\n\n    const stockClusterMap = {\n      \"HDFC BANK\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"HDFCBANK\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"ICICI BANK\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"ICICIBANK\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"SBI\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"SBIN\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"KOTAK BANK\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"AXIS BANK\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"BAJAJ FINANCE\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"CDSL\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"BSE\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"MCX\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"IREDA\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"IRFC\": { group: \"Banking & Fin\", color: \"blue\" },\n      \"EDELWEISS\": { group: \"Banking & Fin\", color: \"blue\" },\n\n      \"NTPC\": { group: \"Energy & Power\", color: \"amber\" },\n      \"ONGC\": { group: \"Energy & Power\", color: \"amber\" },\n      \"POWERGRID\": { group: \"Energy & Power\", color: \"amber\" },\n      \"RELIANCE\": { group: \"Energy & Power\", color: \"amber\" },\n      \"COAL INDIA\": { group: \"Energy & Power\", color: \"amber\" },\n      \"COALINDIA\": { group: \"Energy & Power\", color: \"amber\" },\n      \"BCCL\": { group: \"Energy & Power\", color: \"amber\" },\n      \"NCL\": { group: \"Energy & Power\", color: \"amber\" },\n      \"ADANI\": { group: \"Energy & Power\", color: \"amber\" },\n      \"NATRAJ ENERGY\": { group: \"Energy & Power\", color: \"amber\" },\n      \"NAYARA\": { group: \"Energy & Power\", color: \"amber\" },\n\n      \"TCS\": { group: \"IT & Tech\", color: \"purple\" },\n      \"INFOSYS\": { group: \"IT & Tech\", color: \"purple\" },\n      \"INFY\": { group: \"IT & Tech\", color: \"purple\" },\n      \"WIPRO\": { group: \"IT & Tech\", color: \"purple\" },\n      \"TECH MAHINDRA\": { group: \"IT & Tech\", color: \"purple\" },\n      \"HCLTECH\": { group: \"IT & Tech\", color: \"purple\" },\n      \"COFORGE\": { group: \"IT & Tech\", color: \"purple\" },\n      \"ESDS SOFTWARE\": { group: \"IT & Tech\", color: \"purple\" },\n      \"ORACLE\": { group: \"IT & Tech\", color: \"purple\" },\n      \"NVIDIA\": { group: \"IT & Tech\", color: \"purple\" },\n      \"META\": { group: \"IT & Tech\", color: \"purple\" },\n      \"ALIBABA\": { group: \"IT & Tech\", color: \"purple\" },\n      \"BYTEDANCE\": { group: \"IT & Tech\", color: \"purple\" },\n      \"MONGODB\": { group: \"IT & Tech\", color: \"purple\" },\n      \"ZOMATO\": { group: \"IT & Tech\", color: \"purple\" },\n      \"PAYTM\": { group: \"IT & Tech\", color: \"purple\" },\n      \"SWIGGY\": { group: \"IT & Tech\", color: \"purple\" },\n\n      \"TATA MOTORS\": { group: \"Auto & EV\", color: \"emerald\" },\n      \"MARUTI\": { group: \"Auto & EV\", color: \"emerald\" },\n      \"BAJAJ AUTO\": { group: \"Auto & EV\", color: \"emerald\" },\n      \"HERO MOTOCORP\": { group: \"Auto & EV\", color: \"emerald\" },\n      \"EICHER\": { group: \"Auto & EV\", color: \"emerald\" },\n      \"OLA ELECTRIC\": { group: \"Auto & EV\", color: \"emerald\" },\n      \"OLA ELEC\": { group: \"Auto & EV\", color: \"emerald\" },\n\n      \"HAL\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"BEL\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"BHEL\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"BDL\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"L&T\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"LT\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"RVNL\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"POLYCAB\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"DIXON\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"V-GUARD\": { group: \"Defence & Engg\", color: \"sky\" },\n      \"INDO-MIM\": { group: \"Defence & Engg\", color: \"sky\" },\n\n      \"TATA STEEL\": { group: \"Metals & Mining\", color: \"slate\" },\n      \"JSW STEEL\": { group: \"Metals & Mining\", color: \"slate\" },\n      \"SAIL\": { group: \"Metals & Mining\", color: \"slate\" },\n      \"HINDALCO\": { group: \"Metals & Mining\", color: \"slate\" },\n      \"VEDANTA\": { group: \"Metals & Mining\", color: \"slate\" },\n\n      \"SUN PHARMA\": { group: \"Pharma\", color: \"teal\" },\n      \"CIPLA\": { group: \"Pharma\", color: \"teal\" },\n      \"DR REDDY\": { group: \"Pharma\", color: \"teal\" },\n      \"NATCO PHARMA\": { group: \"Pharma\", color: \"teal\" },\n      \"GUJARAT THEMIS\": { group: \"Pharma\", color: \"teal\" },\n\n      \"ITC\": { group: \"Consumer & Retail\", color: \"rose\" },\n      \"TITAN\": { group: \"Consumer & Retail\", color: \"rose\" },\n      \"TRENT\": { group: \"Consumer & Retail\", color: \"rose\" },\n      \"DMART\": { group: \"Consumer & Retail\", color: \"rose\" },\n      \"ASIAN PAINTS\": { group: \"Consumer & Retail\", color: \"rose\" },\n      \"ULTRATECH\": { group: \"Consumer & Retail\", color: \"rose\" },\n\n      \"BHARTI AIRTEL\": { group: \"Telecom & Aviation\", color: \"indigo\" },\n      \"AIRTEL\": { group: \"Telecom & Aviation\", color: \"indigo\" },\n      \"AIR INDIA\": { group: \"Telecom & Aviation\", color: \"indigo\" },\n      \"JIO\": { group: \"Telecom & Aviation\", color: \"indigo\" },\n\n      \"DLF\": { group: \"Realty & Conglom\", color: \"amber\" },\n      \"GODREJ\": { group: \"Realty & Conglom\", color: \"amber\" },\n      \"TATA SONS\": { group: \"Realty & Conglom\", color: \"amber\" },\n      \"TATA TRUSTS\": { group: \"Realty & Conglom\", color: \"amber\" }\n    };\n\n    let activeRightPanelView = 'ALL';\n    let stockSearchFilterText = '';\n\n    function setRightPanelView(view) {\n      activeRightPanelView = view;\n      if (view === 'CATEGORIES') { treeState.categories = true; }\n      else if (view === 'SECTORS') { treeState.sectors = true; }\n      else if (view === 'STOCKS') { treeState.stocks = true; }\n      else if (view === 'ALL') { treeState.categories = true; treeState.sectors = true; treeState.stocks = true; }\n      renderCategoriesAndStocksSidebar();\n    }\n\n    function onStockSearchInput(val) {\n      stockSearchFilterText = (val || '').trim().toUpperCase();\n      renderCategoriesAndStocksSidebar();\n      // Keep focus in input\n      const input = document.getElementById(\"sidebar-stock-search\");\n      if (input) {\n        input.focus();\n        input.selectionStart = input.selectionEnd = input.value.length;\n      }\n    }\n\n    function toggleTreeNode(section) {\n      treeState[section] = !treeState[section];\n      renderCategoriesAndStocksSidebar();\n    }\n\n    function renderCategoriesAndStocksSidebar() {\n      const container = document.getElementById(\"tree-sidebar-container\");\n      if (!container) return;\n\n      container.innerHTML = \"\";\n\n      const coreStories = stories.filter(s => s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion);\n      const totalIpos = ipoList.length;\n      const anchorCount = coreStories.filter(s => s.isFrontPage).length;\n      const corpEventsCount = stories.filter(s => s.category === \"Corporate Events\").length;\n      const corpApptsCount = stories.filter(s => s.category === \"Corporate Appointments\").length;\n      const corpCount = corpEventsCount + corpApptsCount;\n      const opinionsCount = stories.filter(s => s.isOpinion).length;\n\n      const feCount = stories.filter(s => s.hasFe).length;\n      const bsCount = stories.filter(s => s.hasBs).length;\n\n      // TOP QUICK FILTER TABS\n      const navDiv = document.createElement(\"div\");\n      navDiv.className = \"sticky top-0 z-20 bg-slate-100/95 dark:bg-[#070B14]/95 backdrop-blur-xs p-1 rounded-lg border border-slate-300 dark:border-slate-800 flex items-center justify-between gap-1 text-[11px] font-mono shadow-2xs mb-0.5\";\n      navDiv.innerHTML = `\n        <button onclick=\"setRightPanelView('ALL')\" class=\"flex-1 py-1 rounded text-center transition-all ${activeRightPanelView === 'ALL' ? 'bg-[#1C1917] text-white dark:bg-indigo-600 font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-white/80 dark:hover:bg-slate-800 font-medium'}\">All</button>\n        <button onclick=\"setRightPanelView('CATEGORIES')\" class=\"flex-1 py-1 rounded text-center transition-all ${activeRightPanelView === 'CATEGORIES' ? 'bg-[#1C1917] text-white dark:bg-indigo-600 font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-white/80 dark:hover:bg-slate-800 font-medium'}\">\ud83d\udcc1 Desks</button>\n        <button onclick=\"setRightPanelView('SECTORS')\" class=\"flex-1 py-1 rounded text-center transition-all ${activeRightPanelView === 'SECTORS' ? 'bg-[#1C1917] text-white dark:bg-indigo-600 font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-white/80 dark:hover:bg-slate-800 font-medium'}\">\ud83d\udcc8 Sectors</button>\n        <button onclick=\"setRightPanelView('STOCKS')\" class=\"flex-1 py-1 rounded text-center transition-all ${activeRightPanelView === 'STOCKS' ? 'bg-[#1C1917] text-white dark:bg-indigo-600 font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-white/80 dark:hover:bg-slate-800 font-medium'}\">\ud83c\udfe2 Stocks</button>\n      `;\n      container.appendChild(navDiv);\n\n      // --- SECTION 1: CATEGORIES & PUBLICATIONS TREE CARD ---\n      if (activeRightPanelView === 'ALL' || activeRightPanelView === 'CATEGORIES') {\n        const catCard = document.createElement(\"div\");\n        catCard.className = \"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden\";\n        \n        const isCatOpen = treeState.categories;\n        catCard.innerHTML = `\n          <div class=\"px-2.5 py-1.5 bg-slate-50 dark:bg-slate-900/90 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between cursor-pointer select-none\" onclick=\"toggleTreeNode('categories')\">\n            <div class=\"flex items-center gap-1.5 text-[13px] font-sans font-bold text-slate-900 dark:text-slate-100\">\n              <span class=\"text-amber-600 dark:text-amber-400 text-[11px]\">${isCatOpen ? '\u25bc' : '\u25b6'}</span>\n              <span>\ud83d\udcc1 Desks & Sources</span>\n            </div>\n            ${selectedFeedCategory !== 'ALL' ? `<button onclick=\"event.stopPropagation(); onCategorySelect('ALL');\" class=\"text-[10.5px] font-mono text-amber-600 dark:text-amber-400 font-bold hover:underline\">Reset (\u2715)</button>` : ''}\n          </div>\n        `;\n\n        if (isCatOpen) {\n          const catBody = document.createElement(\"div\");\n          catBody.className = \"p-1.5 flex flex-col gap-1 text-[13px] font-sans\";\n\n          // Sub-group: Publication Source Filter\n          const pubDiv = document.createElement(\"div\");\n          pubDiv.className = \"flex flex-col gap-0.5 mb-1 pb-1.5 border-b border-slate-100 dark:border-slate-800\";\n          pubDiv.innerHTML = `<span class=\"text-[10.5px] font-bold uppercase text-blue-700 dark:text-blue-400 px-1 mb-0.5 tracking-wider\">\ud83d\uddde\ufe0f Filter by Publication</span>`;\n\n          const pubItems = [\n            { id: \"SOURCE_FE\", label: \"\ud83d\udcf0 Financial Express Only\", count: feCount, badge: \"FE\" },\n            { id: \"SOURCE_BS\", label: \"\ud83d\udcf0 Business Standard Only\", count: bsCount, badge: \"BS\" },\n            { id: \"ALL\", label: \"\ud83d\udcd1 All Unified Stories\", count: stories.length, badge: \"ALL\" }\n          ];\n\n          pubItems.forEach(item => {\n            const isSelected = selectedFeedCategory === item.id;\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded flex items-center justify-between transition-colors cursor-pointer ${isSelected ? 'bg-blue-600 text-white font-bold shadow-xs' : 'text-[#090D16] dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800/60 font-medium'}`;\n            btn.innerHTML = `\n              <span class=\"flex items-center gap-1.5 min-w-0 truncate\">\n                <span class=\"text-slate-400 select-none text-[11px] ${isSelected ? 'text-white' : ''}\">\u251c\u2500</span>\n                <span class=\"truncate text-[13px]\">${item.label}</span>\n              </span>\n              <span class=\"text-[11.5px] font-mono shrink-0 ml-1 ${isSelected ? 'text-white/90' : 'text-slate-400 dark:text-slate-500'}\">(${item.count})</span>\n            `;\n            btn.onclick = () => onCategorySelect(isSelected && item.id !== 'ALL' ? 'ALL' : item.id);\n            pubDiv.appendChild(btn);\n          });\n          catBody.appendChild(pubDiv);\n\n          // Sub-group: Core News Desks\n          const coreNewsItems = [\n            { id: \"ANCHOR\", label: \"\ud83d\udcf0 News (Front Page)\", count: anchorCount },\n            { id: \"Sector\", label: \"\ud83c\udfe2 Sector News\", count: stories.filter(s => s.category === \"Sector\").length },\n            { id: \"Economy\", label: \"\ud83d\udcc8 Economy\", count: stories.filter(s => s.category === \"Economy\").length },\n            { id: \"Policy\", label: \"\ud83c\udfdb\ufe0f Policy & Rules\", count: stories.filter(s => s.category === \"Policy\").length },\n            { id: \"Market\", label: \"\ud83d\udcca Market Pulse\", count: stories.filter(s => s.category === \"Market\").length },\n            { id: \"Trade\", label: \"\ud83d\udea2 Trade & FX\", count: stories.filter(s => s.category === \"Trade\").length },\n            { id: \"International News\", label: \"\ud83c\udf10 International\", count: stories.filter(s => s.category === \"International News\").length },\n            { id: \"Others\", label: \"\ud83d\udcd1 Features\", count: stories.filter(s => s.category === \"Others\").length }\n          ];\n\n          const totalCoreDesksCount = coreNewsItems.reduce((acc, item) => acc + item.count, 0);\n\n          const coreDiv = document.createElement(\"div\");\n          coreDiv.className = \"flex flex-col gap-0.5\";\n          coreDiv.innerHTML = `\n            <div class=\"flex items-center justify-between px-1 mb-0.5\">\n              <span class=\"text-[10.5px] font-bold uppercase text-slate-500 dark:text-slate-400 tracking-wider\">\ud83d\udcf0 Core Desks</span>\n              <span class=\"text-[11px] font-mono font-bold text-indigo-600 dark:text-indigo-400\">(${totalCoreDesksCount})</span>\n            </div>\n          `;\n\n          coreNewsItems.forEach(item => {\n            const isSelected = selectedFeedCategory === item.id;\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded flex items-center justify-between transition-colors cursor-pointer ${isSelected ? 'bg-indigo-600 text-white font-bold shadow-xs' : 'text-[#090D16] dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800/60 font-medium'}`;\n            btn.innerHTML = `\n              <span class=\"flex items-center gap-1.5 min-w-0 truncate\">\n                <span class=\"text-slate-400 select-none text-[11px] ${isSelected ? 'text-white' : ''}\">\u251c\u2500</span>\n                <span class=\"truncate text-[13px]\">${item.label}</span>\n              </span>\n              <span class=\"text-[11.5px] font-mono shrink-0 ml-1 ${isSelected ? 'text-white/90' : 'text-slate-400 dark:text-slate-500'}\">(${item.count})</span>\n            `;\n            btn.onclick = () => {\n              if (item.id === 'ANCHOR') switchView('anchor');\n              else onCategorySelect(isSelected ? 'ALL' : item.id);\n            };\n            coreDiv.appendChild(btn);\n          });\n          catBody.appendChild(coreDiv);\n\n          // Sub-group: Specialized Desks\n          const deskItems = [\n            { id: \"IPO_ALL\", label: \"\ud83d\ude80 IPO Central\", count: totalIpos },\n            { id: \"CORPORATE_ALL\", label: \"\ud83c\udfe2 Corporate Desk\", count: corpCount },\n            { id: \"EVENTS\", label: \"\ud83d\udce2 Corp Events\", count: corpEventsCount },\n            { id: \"APPOINTMENTS\", label: \"\ud83d\udc54 Appointments\", count: corpApptsCount },\n            { id: \"OPINIONS\", label: \"\u270d\ufe0f Opinions Desk\", count: opinionsCount }\n          ];\n\n          const totalSpecializedCount = deskItems.reduce((acc, item) => acc + item.count, 0);\n\n          const deskDiv = document.createElement(\"div\");\n          deskDiv.className = \"flex flex-col gap-0.5 pt-1.5 border-t border-slate-100 dark:border-slate-800\";\n          deskDiv.innerHTML = `\n            <div class=\"flex items-center justify-between px-1 mb-0.5\">\n              <span class=\"text-[10.5px] font-bold uppercase text-amber-700 dark:text-amber-400 tracking-wider\">\ud83c\udfdb\ufe0f Specialized Desks</span>\n              <span class=\"text-[11px] font-mono font-bold text-amber-700 dark:text-amber-400\">(${totalSpecializedCount})</span>\n            </div>\n          `;\n\n          deskItems.forEach(item => {\n            const isSelected = selectedFeedCategory === item.id || (item.id === 'IPO_ALL' && currentView === 'ipo') || (item.id === 'CORPORATE_ALL' && currentView === 'corporate');\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded flex items-center justify-between transition-colors cursor-pointer ${isSelected ? 'bg-amber-700 text-white font-bold shadow-xs' : 'text-[#090D16] dark:text-slate-200 hover:bg-amber-50/60 dark:hover:bg-amber-950/30 font-medium'}`;\n            btn.innerHTML = `\n              <span class=\"flex items-center gap-1.5 min-w-0 truncate\">\n                <span class=\"text-slate-400 select-none text-[11px] ${isSelected ? 'text-white' : ''}\">\u251c\u2500</span>\n                <span class=\"truncate text-[13px]\">${item.label}</span>\n              </span>\n              <span class=\"text-[11.5px] font-mono shrink-0 ml-1 ${isSelected ? 'text-white/90' : 'text-amber-700 dark:text-amber-400'}\">(${item.count})</span>\n            `;\n            btn.onclick = () => {\n              if (item.id === 'IPO_ALL') onDeskSelect('ipo');\n              else if (item.id === 'CORPORATE_ALL') onDeskSelect('corporate');\n              else if (item.id === 'EVENTS') selectCorporateSub('EVENTS');\n              else if (item.id === 'APPOINTMENTS') selectCorporateSub('APPOINTMENTS');\n              else if (item.id === 'OPINIONS') onDeskSelect('opinions');\n            };\n            deskDiv.appendChild(btn);\n          });\n          catBody.appendChild(deskDiv);\n\n          catCard.appendChild(catBody);\n        }\n        container.appendChild(catCard);\n      }\n\n      // --- SECTION 2: INDUSTRY SECTORS TREE CARD ---\n      if (activeRightPanelView === 'ALL' || activeRightPanelView === 'SECTORS') {\n        const secCounts = {};\n        stories.forEach(s => {\n          (s.sectors || []).forEach(sec => secCounts[sec] = (secCounts[sec] || 0) + 1);\n        });\n        const sortedSecs = Object.keys(secCounts).sort((a,b) => secCounts[b] - secCounts[a]);\n\n        const secCard = document.createElement(\"div\");\n        secCard.className = \"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden\";\n        \n        const isSecOpen = treeState.sectors;\n        secCard.innerHTML = `\n          <div class=\"px-2.5 py-1.5 bg-slate-50 dark:bg-slate-900/90 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between cursor-pointer select-none\" onclick=\"toggleTreeNode('sectors')\">\n            <div class=\"flex items-center gap-1.5 text-[13px] font-sans font-bold text-slate-900 dark:text-slate-100\">\n              <span class=\"text-indigo-600 dark:text-indigo-400 text-[11px]\">${isSecOpen ? '\u25bc' : '\u25b6'}</span>\n              <span>\ud83d\udcc8 Industry Sectors</span>\n              <span class=\"text-[11.5px] text-slate-500 dark:text-slate-400 font-mono\">(${sortedSecs.length})</span>\n            </div>\n            ${activeSectorFilter ? `<button onclick=\"event.stopPropagation(); activeSectorFilter = null; renderCategoriesAndStocksSidebar(); renderFeedList();\" class=\"text-[10.5px] font-mono text-indigo-600 dark:text-indigo-400 font-bold hover:underline\">Clear (\u2715)</button>` : ''}\n          </div>\n        `;\n\n        if (isSecOpen) {\n          const secBody = document.createElement(\"div\");\n          secBody.className = \"p-1.5 flex flex-col gap-0.5 text-[13px] font-sans\";\n\n          sortedSecs.forEach(sec => {\n            const isSelected = activeSectorFilter === sec;\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded flex items-center justify-between transition-colors cursor-pointer ${isSelected ? 'bg-indigo-600 text-white font-bold shadow-xs' : 'text-[#090D16] dark:text-slate-200 hover:bg-indigo-50/60 dark:hover:bg-indigo-950/30 font-medium'}`;\n            btn.innerHTML = `\n              <span class=\"flex items-center gap-1.5 min-w-0 truncate\">\n                <span class=\"text-slate-400 select-none text-[11px] ${isSelected ? 'text-white' : ''}\">\u251c\u2500</span>\n                <span class=\"truncate text-[13px]\">${sec}</span>\n              </span>\n              <span class=\"text-[11.5px] font-mono shrink-0 ml-1 ${isSelected ? 'text-white/90' : 'text-slate-400 dark:text-slate-500'}\">(${secCounts[sec]})</span>\n            `;\n            btn.onclick = () => {\n              if (activeSectorFilter === sec) {\n                activeSectorFilter = null;\n              } else {\n                activeSectorFilter = sec;\n                activeStockFilter = null;\n                selectedFeedCategory = 'ALL';\n                selectedFeedSentiment = 'ALL';\n                currentSearchQuery = '';\n                const searchInput = document.getElementById(\"global-search\");\n                if (searchInput) searchInput.value = '';\n                const clearBtn = document.getElementById(\"clear-search-btn\");\n                if (clearBtn) clearBtn.classList.add(\"hidden\");\n                if (currentView !== 'feed') {\n                  currentView = 'feed';\n                  const vIpo = document.getElementById(\"view-ipo\");\n                  if (vIpo) vIpo.classList.add(\"hidden\");\n                  const vFeed = document.getElementById(\"view-feed\");\n                  if (vFeed) vFeed.classList.remove(\"hidden\");\n                }\n              }\n              selectedStoryIndex = 0;\n              currentFeedPage = 1;\n              renderCategoriesAndStocksSidebar();\n              renderFeedList();\n            };\n            secBody.appendChild(btn);\n          });\n          secCard.appendChild(secBody);\n        }\n        container.appendChild(secCard);\n      }\n\n      // --- SECTION 3: COMPANY STOCKS CLUSTERED & COLOR-CODED ---\n      if (activeRightPanelView === 'ALL' || activeRightPanelView === 'STOCKS') {\n        const stockCounts = {};\n        stories.forEach(s => {\n          (s.stocks || []).forEach(stk => stockCounts[stk] = (stockCounts[stk] || 0) + 1);\n        });\n        const activeStockKeys = Object.keys(stockCounts);\n\n        const clusters = {};\n        activeStockKeys.forEach(stk => {\n          if (stockSearchFilterText && !stk.includes(stockSearchFilterText)) return;\n          const info = stockClusterMap[stk] || { group: \"Other Companies\", color: \"slate\" };\n          const gName = info.group;\n          if (!clusters[gName]) clusters[gName] = { color: info.color, stocks: [] };\n          clusters[gName].stocks.push({ ticker: stk, count: stockCounts[stk] });\n        });\n\n        const clusterEntries = Object.entries(clusters).sort((a, b) => {\n          const totalA = a[1].stocks.reduce((acc, s) => acc + s.count, 0);\n          const totalB = b[1].stocks.reduce((acc, s) => acc + s.count, 0);\n          return totalB - totalA;\n        });\n\n        const stkCard = document.createElement(\"div\");\n        stkCard.className = \"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden\";\n        \n        const isStkOpen = treeState.stocks;\n        stkCard.innerHTML = `\n          <div class=\"px-2.5 py-1.5 bg-slate-50 dark:bg-slate-900/90 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between cursor-pointer select-none\" onclick=\"toggleTreeNode('stocks')\">\n            <div class=\"flex items-center gap-1.5 text-[13px] font-sans font-bold text-slate-900 dark:text-slate-100\">\n              <span class=\"text-purple-600 dark:text-purple-400 text-[11px]\">${isStkOpen ? '\u25bc' : '\u25b6'}</span>\n              <span>\ud83c\udfe2 Company Stocks</span>\n              <span class=\"text-[11.5px] text-slate-500 dark:text-slate-400 font-mono\">(${activeStockKeys.length})</span>\n            </div>\n            ${activeStockFilter ? `<button onclick=\"event.stopPropagation(); activeStockFilter = null; renderCategoriesAndStocksSidebar(); renderFeedList();\" class=\"text-[10.5px] font-mono text-purple-600 dark:text-purple-400 font-bold hover:underline\">Clear (\u2715)</button>` : ''}\n          </div>\n        `;\n\n        if (isStkOpen) {\n          const stkBody = document.createElement(\"div\");\n          stkBody.className = \"p-1.5 flex flex-col gap-1.5\";\n\n          // Stock search input\n          const searchDiv = document.createElement(\"div\");\n          searchDiv.className = \"relative mb-1\";\n          searchDiv.innerHTML = `\n            <input type=\"text\" value=\"${stockSearchFilterText}\" oninput=\"stockSearchFilterText = this.value.toUpperCase(); renderCategoriesAndStocksSidebar();\" placeholder=\"Filter tickers (e.g. RELIANCE)...\" class=\"w-full text-xs px-2 py-1 rounded bg-slate-100 dark:bg-slate-900 border border-slate-300 dark:border-slate-700 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:border-purple-500 font-mono\">\n            ${stockSearchFilterText ? `<button onclick=\"stockSearchFilterText = ''; renderCategoriesAndStocksSidebar();\" class=\"absolute right-2 top-1 text-slate-400 hover:text-white text-xs\">\u2715</button>` : ''}\n          `;\n          stkBody.appendChild(searchDiv);\n\n          clusterEntries.forEach(([groupName, groupData]) => {\n            const gDiv = document.createElement(\"div\");\n            gDiv.className = \"flex flex-col gap-0.5\";\n            gDiv.innerHTML = `<span class=\"text-[10.5px] font-bold uppercase text-slate-500 dark:text-slate-400 px-1 tracking-wider\">${groupName}</span>`;\n\n            const pillWrap = document.createElement(\"div\");\n            pillWrap.className = \"flex flex-wrap gap-1 px-1 py-0.5\";\n\n            groupData.stocks.forEach(stk => {\n              const isSelected = activeStockFilter === stk.ticker;\n              const btn = document.createElement(\"button\");\n              btn.className = `px-2 py-0.5 rounded text-[11px] font-mono font-bold transition-all cursor-pointer ${isSelected ? 'bg-purple-600 text-white shadow-xs ring-1 ring-purple-400' : 'bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200 hover:bg-purple-100 dark:hover:bg-purple-950/60 border border-slate-200 dark:border-slate-700'}`;\n              btn.innerHTML = `${stk.ticker} <span class=\"opacity-70 text-[10px]\">(${stk.count})</span>`;\n              btn.onclick = () => {\n                if (activeStockFilter === stk.ticker) {\n                  activeStockFilter = null;\n                } else {\n                  activeStockFilter = stk.ticker;\n                  activeSectorFilter = null;\n                  selectedFeedCategory = 'ALL';\n                  selectedFeedSentiment = 'ALL';\n                  currentSearchQuery = '';\n                  const searchInput = document.getElementById(\"global-search\");\n                  if (searchInput) searchInput.value = '';\n                  const clearBtn = document.getElementById(\"clear-search-btn\");\n                  if (clearBtn) clearBtn.classList.add(\"hidden\");\n                  if (currentView !== 'feed') {\n                    currentView = 'feed';\n                    const vIpo = document.getElementById(\"view-ipo\");\n                    if (vIpo) vIpo.classList.add(\"hidden\");\n                    const vFeed = document.getElementById(\"view-feed\");\n                    if (vFeed) vFeed.classList.remove(\"hidden\");\n                  }\n                }\n                selectedStoryIndex = 0;\n                currentFeedPage = 1;\n                renderCategoriesAndStocksSidebar();\n                renderFeedList();\n              };\n              pillWrap.appendChild(btn);\n            });\n\n            gDiv.appendChild(pillWrap);\n            stkBody.appendChild(gDiv);\n          });\n\n          stkCard.appendChild(stkBody);\n        }\n        container.appendChild(stkCard);\n      }\n    }\n\n    function clearAllStockAndSectorFilters() {\n      activeStockFilter = null;\n      activeSectorFilter = null;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      renderCategoriesAndStocksSidebar();\n      if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    function clearStockFilter() {\n      clearAllStockAndSectorFilters();\n    }\n\n    function setFeedSentiment(sent) {\n      selectedFeedSentiment = sent;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      const allBtn = document.getElementById(\"sent-all\");\n      const bullBtn = document.getElementById(\"sent-bullish\");\n      const bearBtn = document.getElementById(\"sent-bearish\");\n      \n      if (allBtn) allBtn.className = sent === \"ALL\" \n        ? \"px-2.5 py-0.5 rounded-md bg-[#1C1917] text-white dark:bg-slate-700 shadow-xs font-semibold\" \n        : \"px-2.5 py-0.5 rounded-md text-slate-800 dark:text-slate-300 hover:bg-white/60 dark:hover:bg-slate-800 font-medium\";\n        \n      if (bullBtn) bullBtn.className = sent === \"BULLISH\" \n        ? \"px-2.5 py-0.5 rounded-md bg-emerald-700 text-white shadow-xs font-semibold flex items-center gap-0.5\" \n        : \"px-2.5 py-0.5 rounded-md text-emerald-900 dark:text-emerald-400 hover:bg-emerald-100/60 dark:hover:bg-emerald-950/40 flex items-center gap-0.5 font-medium\";\n        \n      if (bearBtn) bearBtn.className = sent === \"BEARISH\" \n        ? \"px-2.5 py-0.5 rounded-md bg-rose-700 text-white shadow-xs font-semibold flex items-center gap-0.5\" \n        : \"px-2.5 py-0.5 rounded-md text-rose-900 dark:text-rose-400 hover:bg-rose-100/60 dark:hover:bg-rose-950/40 flex items-center gap-0.5 font-medium\";\n\n      renderFeedList();\n    }\n\n    // ================= FEED LIST & ACTIVE STORY DETAIL (MAX 12 1-LINER STORIES PER PAGE) =================\n    function renderFeedList() {\n      const rawQuery = (document.getElementById(\"global-search\")?.value || \"\").toLowerCase().trim();\n      const queryTokens = rawQuery ? rawQuery.split(\" \").filter(Boolean) : [];\n\n      const displayed = getFilteredStories();\n      const totalStories = displayed.length;\n      const totalPages = Math.ceil(totalStories / FEED_PAGE_SIZE) || 1;\n\n      if (currentFeedPage > totalPages) currentFeedPage = totalPages;\n      if (currentFeedPage < 1) currentFeedPage = 1;\n\n      const startIndex = (currentFeedPage - 1) * FEED_PAGE_SIZE;\n      const endIndex = Math.min(startIndex + FEED_PAGE_SIZE, totalStories);\n      const pageStories = displayed.slice(startIndex, endIndex);\n\n      // Header indicator\n      const countBadge = document.getElementById(\"feed-list-count\");\n      if (countBadge) {\n        countBadge.textContent = totalStories > 0 ? `${startIndex + 1}-${endIndex} of ${totalStories}` : `0 Stories`;\n      }\n\n      // Pagination Controls\n      const pagInfo = document.getElementById(\"feed-pagination-info\");\n      if (pagInfo) {\n        pagInfo.textContent = `Page ${currentFeedPage} / ${totalPages} (${totalStories})`;\n      }\n      const prevBtn = document.getElementById(\"feed-prev-page\");\n      const nextBtn = document.getElementById(\"feed-next-page\");\n      if (prevBtn) {\n        prevBtn.disabled = currentFeedPage <= 1;\n        prevBtn.className = currentFeedPage <= 1 \n          ? \"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-[10.5px] font-medium text-slate-400 dark:text-slate-600 border border-slate-200 dark:border-slate-800 cursor-not-allowed opacity-50\"\n          : \"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-amber-50 text-[10.5px] font-semibold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs cursor-pointer\";\n      }\n      if (nextBtn) {\n        nextBtn.disabled = currentFeedPage >= totalPages;\n        nextBtn.className = currentFeedPage >= totalPages \n          ? \"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-[10.5px] font-medium text-slate-400 dark:text-slate-600 border border-slate-200 dark:border-slate-800 cursor-not-allowed opacity-50\"\n          : \"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-amber-50 text-[10.5px] font-semibold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs cursor-pointer\";\n      }\n\n      const listContainer = document.getElementById(\"feed-list-container\");\n      listContainer.innerHTML = \"\";\n\n      if (totalStories === 0) {\n        listContainer.innerHTML = `\n          <div class=\"p-8 text-center text-slate-400\">\n            <p class=\"text-base font-semibold text-slate-700 dark:text-slate-300\">No news stories found</p>\n            <p class=\"text-[12.5px] mt-1 text-slate-500\">Try broadening your search term or selecting another section.</p>\n            ${rawQuery ? `<button onclick=\"clearSearch()\" class=\"mt-3 px-3 py-1 bg-amber-700 text-white rounded-md text-xs font-semibold\">Clear Search</button>` : ''}\n          </div>\n        `;\n        document.getElementById(\"feed-detail-container\").innerHTML = `<div class=\"p-8 text-center text-slate-400 text-[13.5px]\">Select a story to view analysis.</div>`;\n        return;\n      }\n\n      if (selectedStoryIndex < startIndex || selectedStoryIndex >= endIndex) {\n        selectedStoryIndex = startIndex;\n      }\n\n      pageStories.forEach((s, localIdx) => {\n        const globalIdx = startIndex + localIdx;\n        const isSelected = globalIdx === selectedStoryIndex;\n        const numStr = (globalIdx + 1).toString().padStart(2, '0');\n        const dot = s.sentiment === \"BULLISH\" ? \"bg-emerald-500\" : s.sentiment === \"BEARISH\" ? \"bg-rose-500\" : \"bg-slate-400\";\n\n        const feBadge = s.hasFe ? `<span class=\"px-1.5 py-0.2 rounded text-[10px] font-mono font-extrabold bg-blue-100 text-blue-900 border border-blue-300 dark:bg-blue-950 dark:text-blue-300 shrink-0\">FE</span>` : '';\n        const bsBadge = s.hasBs ? `<span class=\"px-1.5 py-0.2 rounded text-[10px] font-mono font-extrabold bg-amber-100 text-amber-900 border border-amber-300 dark:bg-amber-950 dark:text-amber-300 shrink-0\">BS</span>` : '';\n\n        const activeStyle = \"bg-[#FAF5FF] dark:bg-[#1E1B4B]/70 border-2 border-[#8B5CF6] dark:border-[#A78BFA] shadow-xs text-[#6B21A8] dark:text-[#E9D5FF]\";\n        const inactiveStyle = \"bg-white dark:bg-[#0D1322] border border-slate-200 dark:border-slate-800 hover:border-purple-300 dark:hover:border-purple-900/60 hover:bg-[#FAF5FF]/50 dark:hover:bg-slate-800/50 text-slate-900 dark:text-slate-100\";\n\n        const btn = document.createElement(\"button\");\n        btn.className = `w-full text-left px-3 py-2 rounded-lg transition-all flex items-center justify-between gap-2 mb-1 last:mb-0 cursor-pointer ${isSelected ? activeStyle : inactiveStyle}`;\n        btn.onclick = () => {\n          selectedStoryIndex = globalIdx;\n          renderFeedList();\n          if (window.innerWidth < 1024) {\n            const detailWrapper = document.getElementById(\"feed-detail-wrapper\");\n            if (detailWrapper) {\n              detailWrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });\n            }\n          }\n        };\n\n        btn.innerHTML = `\n          <div class=\"flex items-center gap-2 min-w-0 flex-1\">\n            <span class=\"text-[11.5px] font-mono font-bold ${isSelected ? 'text-[#8B5CF6] dark:text-[#C4B5FD]' : 'text-slate-400'} tabular-nums shrink-0\">${numStr}</span>\n            <span class=\"w-2 h-2 rounded-full ${dot} shrink-0\"></span>\n            ${feBadge}\n            ${bsBadge}\n            ${s.isFrontPage ? `<span class=\"text-[9.5px] font-mono font-bold px-1.5 py-0.2 rounded bg-amber-100 dark:bg-amber-950 text-amber-800 dark:text-amber-300 shrink-0\">P1</span>` : ''}\n            <span class=\"text-[13px] font-sans font-medium truncate ${isSelected ? 'text-[#581C87] dark:text-[#E9D5FF]' : 'text-[#090D16] dark:text-[#F8FAFC]'}\" title=\"${escapeQuotes(s.headline)}\">\n              ${highlightSearchTokens(s.headline, queryTokens)}\n            </span>\n          </div>\n          <span class=\"text-[10px] font-mono text-slate-400 dark:text-slate-500 shrink-0\">${formatPageSource(s.page_numbers)}</span>\n        `;\n        listContainer.appendChild(btn);\n      });\n\n      renderActiveStoryDetail(displayed[selectedStoryIndex], queryTokens);\n      saveNavigationState();\n    }\n\n    function formatPageSource(pageStr) {\n      if (!pageStr) return \"\ud83d\udcf0 FE / BS\";\n      let p = Array.isArray(pageStr) ? pageStr.join(\" / \") : String(pageStr);\n      p = p.trim();\n      if (!p) return \"\ud83d\udcf0 FE / BS\";\n      if (p.startsWith(\"\ud83d\udcf0\")) return p;\n      return `\ud83d\udcf0 ${p}`;\n    }\n\n    function renderActiveStoryDetail(story, queryTokens = []) {\n      const container = document.getElementById(\"feed-detail-container\");\n      if (!container) return;\n\n      if (!story) {\n        container.innerHTML = `\n          <div class=\"h-full flex flex-col items-center justify-center text-center p-8 text-slate-400\">\n            <span class=\"text-4xl mb-3\">\ud83d\udcf0</span>\n            <p class=\"font-mono text-sm font-semibold\">Select any story from the News Wire on the left to read full intelligence breakdown.</p>\n          </div>\n        `;\n        return;\n      }\n\n      const isBullish = (story.sentiment || '').includes('BULLISH');\n      const isBearish = (story.sentiment || '').includes('BEARISH');\n      \n      const sentBadge = isBullish \n        ? `<span class=\"px-3 py-1 rounded text-[11.5px] font-mono font-bold bg-emerald-100 text-emerald-950 border border-emerald-300 dark:bg-emerald-950/70 dark:text-emerald-200\">\ud83d\udfe2 BULLISH</span>`\n        : isBearish \n        ? `<span class=\"px-3 py-1 rounded text-[11.5px] font-mono font-bold bg-rose-100 text-rose-950 border border-rose-300 dark:bg-rose-950/70 dark:text-rose-200\">\ud83d\udd34 BEARISH</span>`\n        : `<span class=\"px-3 py-1 rounded text-[11.5px] font-mono font-bold bg-slate-200 text-slate-900 border border-slate-300 dark:bg-slate-800 dark:text-slate-200\">\u26aa NEUTRAL</span>`;\n\n      const tickerBadges = (story.tickers || []).map(t => `<span class=\"px-2.5 py-1 text-[11.5px] font-mono font-bold rounded bg-indigo-100 text-indigo-950 border border-indigo-300 dark:bg-indigo-950/80 dark:text-indigo-200\">${t}</span>`).join('');\n\n      const briefSentences = (story.brief_details || \"\").split(/(?<=[.?!])\\s+/).filter(Boolean);\n      const bullets = story.bullet_points || story.detailed_points || [];\n\n      container.innerHTML = `\n        <!-- TOP ROW: METADATA & ACTION BUTTONS -->\n        <div class=\"flex items-center justify-between gap-2 pb-3 border-b border-slate-200 dark:border-slate-800 shrink-0 text-[12px] font-mono\">\n          <div class=\"flex items-center gap-2 flex-wrap\">\n            <button id=\"feed-open-col1-btn\" onclick=\"toggleCol1()\" class=\"${isCol1Collapsed ? 'flex' : 'hidden'} items-center gap-1 font-mono text-[11px] font-bold px-2.5 py-1 rounded border border-indigo-300 dark:border-indigo-800 bg-indigo-50 dark:bg-indigo-950/70 text-indigo-700 dark:text-indigo-300 hover:bg-indigo-100 shadow-2xs cursor-pointer\" title=\"Expand Column 1 (News Wire)\">\n              <span>\ud83d\udcf0 Wire \u00bb</span>\n            </button>\n            <span class=\"font-bold px-2.5 py-1 rounded bg-slate-200 text-slate-900 dark:bg-slate-800 dark:text-white\">${story.category}</span>\n            ${story.isFrontPage ? `<span class=\"font-bold px-2.5 py-1 rounded bg-amber-200 text-amber-950 dark:bg-amber-950/80 dark:text-amber-200\">\ud83d\udcf0 PAGE 1 ANCHOR</span>` : ''}\n            ${story.hasFe ? `<span class=\"font-extrabold px-2.5 py-1 rounded bg-blue-100 text-blue-950 border border-blue-300 dark:bg-blue-950 dark:text-blue-200\">Financial Express</span>` : ''}\n            ${story.hasBs ? `<span class=\"font-extrabold px-2.5 py-1 rounded bg-amber-100 text-amber-950 border border-amber-300 dark:bg-amber-950 dark:text-amber-200\">Business Standard</span>` : ''}\n            <span class=\"font-semibold px-2.5 py-1 rounded bg-slate-100 dark:bg-slate-800/80 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700\">${formatPageSource(story.page_numbers)}</span>\n          </div>\n          <div class=\"flex items-center gap-2\">\n            ${sentBadge}\n            <button onclick=\"copyStoryById(${story.id})\" class=\"text-slate-800 hover:text-slate-950 dark:text-slate-200 dark:hover:text-white font-mono flex items-center gap-1 font-bold px-3 py-1 rounded border border-slate-300 dark:border-slate-700 bg-white dark:bg-[#141A2E] shadow-2xs cursor-pointer\" title=\"Copy story summary\">\n              \ud83d\udccb Copy\n            </button>\n          </div>\n        </div>\n\n        <!-- HEADLINE -->\n        <h1 class=\"text-[21px] sm:text-[23px] font-extrabold text-[#05080F] dark:text-white leading-tight tracking-tight mt-3 mb-4 shrink-0 flex items-center flex-wrap gap-2\">\n          <span>${highlightSearchTokens(highlightNumbers(story.headline), queryTokens)}</span>\n          ${(story.tickers && story.tickers.length > 0) ? tickerBadges : ''}\n        </h1>\n\n        <!-- EXPANSIVE EXECUTIVE CONTENT STACK (2-COLUMN GRID ON XL SCREENS) -->\n        <div class=\"grid grid-cols-1 xl:grid-cols-2 gap-4 flex-1\">\n          \n          <!-- LEFT COLUMN: GIST & CATALYST -->\n          <div class=\"flex flex-col gap-4\">\n            <!-- \u26a1 1. EXECUTIVE GIST -->\n            <div class=\"rounded-xl border-2 border-indigo-200 dark:border-indigo-900/80 bg-indigo-50/40 dark:bg-[#12172E] p-4 sm:p-5 shadow-xs flex flex-col gap-3\">\n              <div class=\"flex items-center justify-between border-b border-indigo-200/80 dark:border-indigo-900/60 pb-2\">\n                <span class=\"text-[13px] font-mono font-extrabold uppercase tracking-wider text-indigo-950 dark:text-indigo-200 flex items-center gap-2\">\n                  <span>\u26a1</span> <span>1. EXECUTIVE GIST</span>\n                </span>\n                <span class=\"text-[11px] font-mono font-bold px-2.5 py-0.5 rounded bg-indigo-100 text-indigo-950 dark:bg-indigo-900 dark:text-indigo-200 border border-indigo-300 dark:border-indigo-700\">Key Takeaway</span>\n              </div>\n              <div class=\"space-y-2.5\">\n                ${briefSentences.map(sent => `\n                  <div class=\"flex items-start gap-3 bg-white dark:bg-[#0A0E1A] p-3 rounded-lg border border-indigo-100 dark:border-slate-800 text-[14px] sm:text-[15px] text-[#090D16] dark:text-[#F8FAFC] leading-relaxed font-normal shadow-2xs font-sans\">\n                    <span class=\"text-indigo-600 dark:text-indigo-400 font-extrabold select-none text-sm\">\u25b8</span>\n                    <span class=\"leading-relaxed\">${highlightSearchTokens(highlightNumbers(sent), queryTokens)}</span>\n                  </div>\n                `).join('')}\n              </div>\n            </div>\n\n            <!-- \ud83d\udca1 2. CATALYST & MARKET IMPACT -->\n            <div class=\"rounded-xl border-2 ${isBullish ? 'border-emerald-500 bg-emerald-50/50 dark:bg-[#064E3B]/25 dark:border-emerald-600' : isBearish ? 'border-rose-500 bg-rose-50/50 dark:bg-[#881337]/25 dark:border-rose-600' : 'border-slate-300 bg-slate-50/80 dark:bg-slate-900/50 dark:border-slate-700'} p-4 sm:p-5 shadow-xs flex flex-col gap-3\">\n              <div class=\"flex items-center justify-between border-b ${isBullish ? 'border-emerald-200 dark:border-emerald-900/60' : isBearish ? 'border-rose-200 dark:border-rose-900/60' : 'border-slate-200 dark:border-slate-800'} pb-2\">\n                <span class=\"text-[13px] font-mono font-extrabold uppercase tracking-wider ${isBullish ? 'text-emerald-950 dark:text-emerald-300' : isBearish ? 'text-rose-950 dark:text-rose-300' : 'text-slate-900 dark:text-slate-200'} flex items-center gap-2\">\n                  <span>\ud83d\udca1</span> <span>2. CATALYST & MARKET IMPACT</span>\n                </span>\n                <span class=\"text-[11px] font-mono font-extrabold uppercase px-2.5 py-0.5 rounded ${isBullish ? 'bg-emerald-200 text-emerald-950 dark:bg-emerald-900 dark:text-emerald-200' : isBearish ? 'bg-rose-200 text-rose-950 dark:bg-rose-900 dark:text-rose-200' : 'bg-slate-200 text-slate-900 dark:bg-slate-800 dark:text-slate-200'}\">${story.sentiment} THESIS</span>\n              </div>\n              \n              <div class=\"space-y-3\">\n                <!-- Trigger / Catalyst Sub-block -->\n                <div class=\"bg-white/90 dark:bg-[#0A0E1A]/90 p-3 rounded-lg border ${isBullish ? 'border-emerald-200/80 dark:border-emerald-900/60' : isBearish ? 'border-rose-200/80 dark:border-rose-900/60' : 'border-slate-200 dark:border-slate-800'} shadow-2xs\">\n                  <div class=\"flex items-center gap-1.5 font-mono text-[11px] font-extrabold uppercase tracking-wider mb-1.5 ${isBullish ? 'text-emerald-800 dark:text-emerald-300' : isBearish ? 'text-rose-800 dark:text-rose-300' : 'text-slate-700 dark:text-slate-300'}\">\n                    <span>\u26a1</span> <span>Primary Catalyst / Trigger:</span>\n                  </div>\n                  <div class=\"text-[13.5px] sm:text-[14.5px] text-[#090D16] dark:text-[#F8FAFC] leading-relaxed font-sans font-medium\">\n                    ${highlightSearchTokens(highlightNumbers(story.catalyst), queryTokens)}\n                  </div>\n                </div>\n\n                <!-- Financial & Valuation Transmission Impact -->\n                <div class=\"bg-white dark:bg-[#0A0E1A] p-3 rounded-lg border ${isBullish ? 'border-emerald-200/80 dark:border-emerald-900/60' : isBearish ? 'border-rose-200/80 dark:border-rose-900/60' : 'border-slate-200 dark:border-slate-800'} shadow-2xs\">\n                  <div class=\"flex items-center gap-1.5 font-mono text-[11px] font-extrabold uppercase tracking-wider mb-1.5 ${isBullish ? 'text-emerald-800 dark:text-emerald-300' : isBearish ? 'text-rose-800 dark:text-rose-300' : 'text-slate-700 dark:text-slate-300'}\">\n                    <span>\ud83d\udcca</span> <span>Market, Sector & Valuation Impact:</span>\n                  </div>\n                  <div class=\"text-[13.5px] sm:text-[14.5px] text-[#090D16] dark:text-[#F8FAFC] leading-relaxed font-sans\">\n                    ${highlightSearchTokens(highlightNumbers(story.market_impact || story.sentimentReasoning), queryTokens)}\n                  </div>\n                </div>\n\n                <!-- Institutional Thesis Note -->\n                ${story.sentimentReasoning && story.sentimentReasoning !== story.market_impact ? `\n                  <div class=\"px-3 py-2 rounded-lg bg-slate-100/80 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 text-[12px] font-mono flex items-start gap-2 text-slate-700 dark:text-slate-300\">\n                    <span class=\"font-bold text-slate-900 dark:text-slate-100\">\ud83d\udccc Stance:</span>\n                    <span>${highlightSearchTokens(highlightNumbers(story.sentimentReasoning), queryTokens)}</span>\n                  </div>\n                ` : ''}\n              </div>\n            </div>\n          </div>\n\n          <!-- RIGHT COLUMN: KEY ANALYST DATA POINTS -->\n          <div class=\"flex flex-col gap-4\">\n            <!-- \ud83d\udccc 3. KEY ANALYST DATA POINTS -->\n            <div class=\"h-full rounded-xl border-2 border-amber-300/80 dark:border-amber-900/60 bg-[#FDFBF7] dark:bg-[#161311] p-4 sm:p-5 shadow-xs flex flex-col gap-3\">\n              <div class=\"flex items-center justify-between border-b border-amber-200 dark:border-amber-950 pb-2\">\n                <span class=\"text-[13px] font-mono font-extrabold uppercase tracking-wider text-amber-950 dark:text-amber-200 flex items-center gap-2\">\n                  <span>\ud83d\udccc</span> <span>3. KEY ANALYST DATA POINTS</span>\n                </span>\n                <span class=\"text-[11px] font-mono font-bold px-2.5 py-0.5 rounded bg-amber-100 text-amber-950 dark:bg-amber-900 dark:text-amber-200 border border-amber-300 dark:border-amber-700\">Metrics & Facts</span>\n              </div>\n              <ul class=\"space-y-2.5 flex-1\">\n                ${bullets.map(b => `\n                  <li class=\"flex items-start gap-3 bg-white dark:bg-[#0E0C0A] p-3 rounded-lg border border-amber-100 dark:border-[#2D2319] text-[14px] sm:text-[15px] text-[#23170E] dark:text-[#F1E8DF] leading-relaxed font-sans shadow-2xs\">\n                    <span class=\"text-amber-700 dark:text-amber-400 shrink-0 font-bold mt-0.5 text-sm\">\u2022</span>\n                    <span class=\"leading-relaxed\">${highlightSearchTokens(highlightNumbers(b), queryTokens)}</span>\n                  </li>\n                `).join('')}\n              </ul>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- \ud83c\udfe2 4. IMPACTED TICKERS & SECTOR EXPOSURE STRIP -->\n        ${((story.tickers && story.tickers.length > 0) || (story.sectors && story.sectors.length > 0)) ? `\n        <div class=\"rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/60 p-3.5 flex items-center justify-between gap-3 flex-wrap shrink-0\">\n          <div class=\"flex items-center gap-2 flex-wrap\">\n            <span class=\"text-[11px] font-mono font-bold uppercase text-slate-500 dark:text-slate-400\">Market Exposure:</span>\n            ${(story.tickers || []).map(t => `<span class=\"px-2.5 py-1 text-[11.5px] font-mono font-bold rounded bg-indigo-100 text-indigo-950 border border-indigo-300 dark:bg-indigo-950 dark:text-indigo-200\">${t}</span>`).join('')}\n            ${(story.sectors || []).map(sec => `<span class=\"px-2.5 py-1 text-[11.5px] font-mono font-medium rounded bg-slate-200 text-slate-900 dark:bg-slate-800 dark:text-slate-200\">${sec}</span>`).join('')}\n          </div>\n          <span class=\"text-[11.5px] font-mono text-slate-400 dark:text-slate-500\">${formatPageSource(story.page_numbers)} \u2022 ${story.source_paper || 'FE / BS'}</span>\n        </div>\n        ` : ''}\n\n        <!-- \ud83c\udfc1 END OF STORY FOOTER BAR -->\n        <div class=\"mt-5 pt-3 pb-3 border-t border-slate-200 dark:border-slate-800 flex items-center justify-between text-xs font-mono text-slate-400 shrink-0\">\n          <span class=\"flex items-center gap-2 font-bold text-slate-600 dark:text-slate-300\">\n            <span>\ud83c\udfc1</span> <span>End of Story #${story.id} (${formatPageSource(story.page_numbers)})</span>\n          </span>\n          <div class=\"flex items-center gap-2\">\n            <button onclick=\"navigateStory(-1)\" class=\"px-3 py-1 rounded bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold border border-slate-300 dark:border-slate-700 shadow-2xs\">\u25c0 Prev Story (K)</button>\n            <button onclick=\"navigateStory(1)\" class=\"px-3 py-1 rounded bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold border border-slate-300 dark:border-slate-700 shadow-2xs\">Next Story (J) \u25b6</button>\n          </div>\n        </div>\n      `;\n    }\n\n    function renderRawArticleText(story, queryTokens = []) {\n      if (!story) return \"\";\n      if (story.raw_news_text && story.raw_news_text.trim().length > 20) {\n        return highlightSearchTokens(highlightNumbers(story.raw_news_text.trim()), queryTokens);\n      }\n      const parts = [\n        `<b>${story.headline}</b>`,\n        `<i>Source: ${story.page_numbers || 'Print Edition'} | Desk: ${story.category}</i>\\n`,\n        story.brief_details,\n        \"\",\n        \"<b>Key Details & Reporting Facts:</b>\",\n        ...(story.bullet_points || []).map(bp => `\u2022 ${bp}`)\n      ];\n      if (story.sentimentReasoning) {\n        parts.push(\"\", `<b>Analyst Thesis:</b> ${story.sentimentReasoning}`);\n      }\n      return highlightSearchTokens(highlightNumbers(parts.join('\\n')), queryTokens);\n    }\n\n    function highlightNumbers(text) {\n      if (!text) return \"\";\n      return text.replace(/(\\b\\d+(?:\\.\\d+)?%|\\b\u20b9\\s?[\\d,]+(?:\\.\\d+)?(?:\\s?(?:cr|crore|lakh|bn|billion|tn|trillion))?|\\b\\$[\\d,]+(?:\\.\\d+)?(?:\\s?(?:bn|billion|million|mn|tn))?|\\b[\\d,]+(?:\\.\\d+)?\\s?(?:crore|lakh|billion|million)\\b)/gi, '<span class=\"text-slate-950 dark:text-amber-300 font-semibold font-mono\">$1</span>');\n    }\n\n    function highlightSearchTokens(text, tokens) {\n      if (!text || !tokens || tokens.length === 0) return text;\n      let result = text;\n      tokens.forEach(tok => {\n        if (!tok || tok.length < 2) return;\n        const regex = new RegExp(`(${escapeRegExp(tok)})`, 'gi');\n        result = result.replace(regex, '<mark>$1</mark>');\n      });\n      return result;\n    }\n\n    function escapeRegExp(string) {\n      return string.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    }\n\n    function escapeQuotes(str) {\n      return str.replace(/'/g, \"\\\\'\").replace(/\"/g, '&quot;');\n    }\n\n    function copyToClipboard(text) {\n      navigator.clipboard.writeText(text);\n      alert(\"Copied to clipboard!\");\n    }\n\n    document.addEventListener(\"keydown\", (e) => {\n      if (e.target.tagName === \"INPUT\" || e.target.tagName === \"SELECT\" || e.target.tagName === \"TEXTAREA\") return;\n      if (e.key === \"ArrowRight\" || e.key === \"ArrowDown\" || e.key === \"j\") {\n        e.preventDefault();\n        navigateStory(1);\n      } else if (e.key === \"ArrowLeft\" || e.key === \"ArrowUp\" || e.key === \"k\") {\n        e.preventDefault();\n        navigateStory(-1);\n      } else if (e.key === \"1\") switchView('feed');\n      else if (e.key === \"2\") switchView('anchor');\n      else if (e.key === \"3\") switchView('ipo');\n      else if (e.key === \"/\") { e.preventDefault(); document.getElementById(\"global-search\").focus(); }\n    });\n\n    // ================= BUSINESS STANDARD 1-CLICK AUTH & SYNC =================\n    const BS_BOOKMARKLET_JS = \"javascript:(function(){try{if(!window.location.hostname.includes('business-standard.com')){alert('\ud83d\udccc Please click this bookmark while viewing https://epaper.business-standard.com (logged in).\\\\n\\\\nTo install: Drag this button up to your browser Bookmarks Bar (Cmd+Shift+B)!');return;}const cookies=document.cookie;if(!cookies||!cookies.includes('=')){alert('\u26a0\ufe0f No cookies found! Please log in to https://epaper.business-standard.com first.');return;}const endpoint='https://finpress.deb5045ai.workers.dev/api/session/bs';const toast=document.createElement('div');toast.style.cssText='position:fixed;top:20px;right:20px;z-index:999999;background:#1e1b4b;color:#fff;padding:16px 20px;border-radius:12px;font-family:sans-serif;font-size:14px;box-shadow:0 10px 25px rgba(0,0,0,0.5);border:2px solid #8b5cf6;max-width:380px;';toast.innerHTML='<b>FinPress Sync</b><br>\u23f3 Syncing your Business Standard session...';document.body.appendChild(toast);fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cookieString:cookies,domain:window.location.hostname,url:window.location.href,localStorage:JSON.stringify(window.localStorage)}),mode:'cors'}).then(r=>r.json()).then(data=>{if(data.success){toast.style.borderColor='#10b981';toast.innerHTML='<b>FinPress Sync \u2705</b><br>Session synced & GitHub Actions triggered!<br><small>Your live dashboard will update with today\\\\'s BS paper in 2-3 minutes.</small>';setTimeout(()=>toast.remove(),7000);}else{toast.style.borderColor='#ef4444';toast.innerHTML='<b>FinPress Sync \u26a0\ufe0f</b><br>'+(data.message||'Error syncing session.');setTimeout(()=>toast.remove(),7000);}}).catch(err=>{toast.style.borderColor='#ef4444';toast.innerHTML='<b>FinPress Sync \u274c</b><br>Failed to connect: '+err.message;setTimeout(()=>toast.remove(),7000);});}catch(e){alert('FinPress Sync Error: '+e.message);}})();\";\n\n    function openBsSyncModal() {\n      const modal = document.getElementById(\"bs-sync-modal\");\n      if (modal) {\n        modal.classList.remove(\"hidden\");\n        modal.classList.add(\"flex\");\n      }\n    }\n\n    function closeBsSyncModal() {\n      const modal = document.getElementById(\"bs-sync-modal\");\n      if (modal) {\n        modal.classList.remove(\"flex\");\n        modal.classList.add(\"hidden\");\n      }\n    }\n\n    function initBsBookmarklet() {\n      const link = document.getElementById(\"bs-bookmarklet-link\");\n      if (link) {\n        link.setAttribute(\"href\", BS_BOOKMARKLET_JS);\n        link.onclick = (e) => {\n          if (!window.location.hostname.includes(\"business-standard.com\")) {\n            e.preventDefault();\n            alert(\"\ud83d\udc49 Don't click here directly!\\n\\n1. Press Cmd+Shift+B (Mac) or Ctrl+Shift+B (Windows) to show your Bookmarks Bar.\\n2. DRAG this orange button up into your Bookmarks Bar.\\n3. Open https://epaper.business-standard.com and click the bookmark from your top bar!\");\n          }\n        };\n      }\n    }\n\n    function copyBookmarkletCode() {\n      navigator.clipboard.writeText(BS_BOOKMARKLET_JS).then(() => {\n        alert(\"Bookmarklet JavaScript copied to clipboard! You can paste this as a bookmark URL or in DevTools Console on epaper.business-standard.com.\");\n      }).catch(err => {\n        prompt(\"Copy this bookmarklet code:\", BS_BOOKMARKLET_JS);\n      });\n    }\n\n    async function submitManualBsCookie() {\n      const input = document.getElementById(\"bs-cookie-input\");\n      const status = document.getElementById(\"bs-manual-status\");\n      if (!input || !status) return;\n\n      const rawVal = input.value.trim();\n      if (!rawVal) {\n        status.textContent = \"\u274c Please paste cookie or JSON\";\n        status.className = \"text-xs font-mono font-bold text-rose-500\";\n        return;\n      }\n\n      status.textContent = \"\u23f3 Syncing & triggering GA...\";\n      status.className = \"text-xs font-mono font-bold text-indigo-400\";\n\n      try {\n        let payload;\n        try {\n          payload = JSON.parse(rawVal);\n        } catch {\n          payload = { cookieString: rawVal };\n        }\n\n        const res = await fetch(\"/api/session/bs\", {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (data.success) {\n          status.textContent = \"\u2705 Session synced & GA triggered!\";\n          status.className = \"text-xs font-mono font-bold text-emerald-400\";\n          setTimeout(() => {\n            closeBsSyncModal();\n            loadData();\n          }, 2000);\n        } else {\n          status.textContent = `\u274c ${data.error || 'Failed'}`;\n          status.className = \"text-xs font-mono font-bold text-rose-500\";\n        }\n      } catch (err) {\n        status.textContent = `\u274c Error: ${err.message}`;\n        status.className = \"text-xs font-mono font-bold text-rose-500\";\n      }\n    }\n\n    async function triggerGitHubPipeline() {\n      let token = localStorage.getItem(\"finpress_gh_token\");\n      if (!token) {\n        token = prompt(\"Enter your GitHub Personal Access Token (with 'repo' or 'workflow' scope) to trigger GitHub Actions directly from this button:\\n\\n(It will be stored securely in your browser localStorage)\", \"\");\n        if (!token || !token.trim()) return;\n        localStorage.setItem(\"finpress_gh_token\", token.trim());\n      }\n\n      const alertBanner = document.getElementById(\"source-alert-banner\");\n      const alertText = document.getElementById(\"source-alert-text\");\n      if (alertBanner && alertText) {\n        alertText.innerHTML = \"\u23f3 <b>Triggering GitHub Actions pipeline in cloud...</b>\";\n        alertBanner.classList.remove(\"hidden\");\n      }\n\n      try {\n        const res = await fetch(\"/api/trigger-pipeline\", {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ token: token.trim() })\n        });\n        const data = await res.json();\n        if (data.success) {\n          if (alertBanner && alertText) {\n            alertText.innerHTML = `\ud83d\ude80 <b>GitHub Actions Triggered!</b> Downloading & analyzing papers in cloud. <a href=\"https://github.com/vedarthain/FinPress/actions/workflows/2_fetch_business_standard.yml\" target=\"_blank\" class=\"underline font-bold ml-2 text-indigo-300\">View Live Run \u2197</a>`;\n            alertBanner.classList.remove(\"hidden\");\n          }\n          alert(\"\ud83d\ude80 GitHub Actions pipeline triggered successfully!\\n\\nYour dashboard will automatically refresh in 2-3 minutes.\");\n        } else {\n          if (data.needsToken || res.status === 401) {\n            localStorage.removeItem(\"finpress_gh_token\");\n            alert(\"Invalid or expired GitHub Token. Please try again.\");\n          } else {\n            alert(\"Failed to trigger pipeline: \" + (data.error || \"Unknown error\"));\n          }\n        }\n      } catch (err) {\n        alert(\"Error: \" + err.message);\n      }\n    }\n\n    initTheme();\n    initFontSize();\n    initBsBookmarklet();\n    fetchDates();\n    loadData();\n\n\n    // ================= IPO HUB CONTROLLER FUNCTIONS =================\n    function setIpoViewMode(mode) {\n      activeIpoMode = mode;\n      const trackerBtn = document.getElementById(\"ipo-mode-tracker-btn\");\n      const listedBtn = document.getElementById(\"ipo-mode-listed-btn\");\n      const trackerWrap = document.getElementById(\"ipo-tracker-table-wrap\");\n      const listedWrap = document.getElementById(\"ipo-listed-table-wrap\");\n      const subfilter = document.getElementById(\"ipo-subfilter-container\");\n\n      if (mode === 'tracker') {\n        if (trackerBtn) trackerBtn.className = \"px-3 py-1.5 rounded-lg bg-[#1C1917] text-white dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer\";\n        if (listedBtn) listedBtn.className = \"px-3 py-1.5 rounded-lg text-slate-700 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 cursor-pointer\";\n        if (trackerWrap) trackerWrap.classList.remove(\"hidden\");\n        if (listedWrap) listedWrap.classList.add(\"hidden\");\n        if (subfilter) subfilter.classList.remove(\"hidden\");\n        renderIpoTrackerTable();\n      } else {\n        if (listedBtn) listedBtn.className = \"px-3 py-1.5 rounded-lg bg-[#1C1917] text-white dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer\";\n        if (trackerBtn) trackerBtn.className = \"px-3 py-1.5 rounded-lg text-slate-700 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 cursor-pointer\";\n        if (listedWrap) listedWrap.classList.remove(\"hidden\");\n        if (trackerWrap) trackerWrap.classList.add(\"hidden\");\n        if (subfilter) subfilter.classList.add(\"hidden\");\n        renderAlreadyListedTable();\n      }\n    }\n\n    function setIpoFilterCategory(cat) {\n      activeIpoCategory = cat;\n      ['all', 'mb', 'sme'].forEach(c => {\n        const btn = document.getElementById(`ipo-filter-${c}`);\n        if (!btn) return;\n        if ((c === 'all' && cat === 'ALL') || (c === 'mb' && cat === 'MAINBOARD') || (c === 'sme' && cat === 'SME')) {\n          btn.className = \"px-2.5 py-1 rounded-md bg-slate-900 text-white dark:bg-indigo-600 dark:text-white font-bold shadow-2xs\";\n        } else {\n          btn.className = \"px-2.5 py-1 rounded-md text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800\";\n        }\n      });\n      renderIpoTrackerTable();\n    }\n\n    function onIpoSearchInput(val) {\n      ipoSearchQuery = (val || '').toLowerCase().trim();\n      if (activeIpoMode === 'tracker') renderIpoTrackerTable();\n      else renderAlreadyListedTable();\n    }\n\n    function renderIpoTrackerTable() {\n      const tbody = document.getElementById(\"ipo-table-body\");\n      const countLabel = document.getElementById(\"ipo-table-visible-count\");\n      if (!tbody) return;\n\n      tbody.innerHTML = \"\";\n      let list = ipoList || [];\n\n      if (activeIpoCategory === 'MAINBOARD') {\n        list = list.filter(i => !(i.exchange || '').includes(\"SME\") && !(i.exchange || '').includes(\"Emerge\"));\n      } else if (activeIpoCategory === 'SME') {\n        list = list.filter(i => (i.exchange || '').includes(\"SME\") || (i.exchange || '').includes(\"Emerge\"));\n      }\n\n      if (ipoSearchQuery) {\n        list = list.filter(i => {\n          const full = (i.company + \" \" + i.exchange + \" \" + i.stage + \" \" + (i.details || '')).toLowerCase();\n          return full.includes(ipoSearchQuery);\n        });\n      }\n\n      if (countLabel) countLabel.textContent = list.length;\n\n      // Update KPI counters\n      const kpiTotal = document.getElementById(\"ipo-kpi-total\");\n      const kpiBidding = document.getElementById(\"ipo-kpi-bidding\");\n      const kpiDrhp = document.getElementById(\"ipo-kpi-drhp\");\n      if (kpiTotal) kpiTotal.textContent = (ipoList || []).length;\n      if (kpiBidding) kpiBidding.textContent = (ipoList || []).filter(i => (i.stage || '').includes(\"Bidding\")).length;\n      if (kpiDrhp) kpiDrhp.textContent = (ipoList || []).filter(i => (i.stage || '').includes(\"DRHP\")).length;\n\n      if (list.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"9\" class=\"py-12 text-center text-slate-400 font-mono\">No active IPO issues match the selected criteria.</td></tr>`;\n        return;\n      }\n\n      list.forEach((item, idx) => {\n        const isSme = (item.exchange || '').includes(\"SME\") || (item.exchange || '').includes(\"Emerge\");\n        const stageColor = (item.stage || '').includes(\"Bidding\") \n          ? \"bg-emerald-100 text-emerald-950 border-emerald-300 dark:bg-emerald-950/80 dark:text-emerald-300\"\n          : (item.stage || '').includes(\"DRHP\")\n          ? \"bg-amber-100 text-amber-950 border-amber-300 dark:bg-amber-950/80 dark:text-amber-300\"\n          : \"bg-blue-100 text-blue-950 border-blue-300 dark:bg-blue-950/80 dark:text-blue-300\";\n\n        const tr = document.createElement(\"tr\");\n        tr.className = \"hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors\";\n        tr.innerHTML = `\n          <td class=\"py-3 px-3 text-center font-mono font-bold text-slate-400\">${idx + 1}</td>\n          <td class=\"py-3 px-3\">\n            <div class=\"font-bold text-[#090D16] dark:text-white leading-tight\">${item.company}</div>\n            <div class=\"flex items-center gap-1.5 mt-1\">\n              <span class=\"text-[10px] font-mono font-bold px-1.5 py-0.2 rounded ${isSme ? 'bg-purple-100 text-purple-950 dark:bg-purple-950 dark:text-purple-300' : 'bg-indigo-100 text-indigo-950 dark:bg-indigo-950 dark:text-indigo-300'}\">${isSme ? 'SME EMERGE' : 'MAINBOARD'}</span>\n              <span class=\"text-[11px] font-mono text-slate-400\">${item.exchange || 'NSE / BSE'}</span>\n            </div>\n          </td>\n          <td class=\"py-3 px-3 font-mono text-[12px] text-slate-600 dark:text-slate-300\">\n            <div>Open: <b>${item.openDate || 'Oct 2026'}</b></div>\n            <div class=\"text-slate-400\">Close: ${item.closeDate || 'Oct 2026'}</div>\n          </td>\n          <td class=\"py-3 px-3 font-mono font-bold text-slate-900 dark:text-slate-100\">${item.priceBand || '\u20b9140 - \u20b9148'}</td>\n          <td class=\"py-3 px-3 font-mono font-bold text-indigo-600 dark:text-indigo-400\">${item.size || '\u20b9500 Cr'}</td>\n          <td class=\"py-3 px-3 font-mono text-slate-600 dark:text-slate-400\">${item.lotSize || '100 Shares'}</td>\n          <td class=\"py-3 px-3 font-mono\">\n            <div class=\"flex items-center gap-1.5\">\n              <span class=\"font-bold text-emerald-600 dark:text-emerald-400 text-[12.5px]\">${item.subscription || '14.5x'}</span>\n              <span class=\"text-[10px] text-slate-400\">Total</span>\n            </div>\n            <div class=\"text-[10.5px] text-slate-400\">QIB: 22x | NII: 15x | Retail: 6x</div>\n          </td>\n          <td class=\"py-3 px-3\">\n            <span class=\"px-2.5 py-0.5 rounded-full text-[11px] font-mono font-bold border ${stageColor}\">\n              ${item.stage || '\ud83d\udccb DRHP Filed'}\n            </span>\n          </td>\n          <td class=\"py-3 px-3 text-center\">\n            <button onclick=\"openStoryModalById(${item.storyId || 1})\" class=\"px-2.5 py-1 rounded bg-slate-100 dark:bg-slate-800 hover:bg-indigo-50 text-indigo-600 dark:text-indigo-400 font-mono text-[11px] font-bold border border-slate-200 dark:border-slate-700 cursor-pointer\">\n              Details \u2197\n            </button>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function renderAlreadyListedTable() {\n      const tbody = document.getElementById(\"ipo-listed-table-body\");\n      const countLabel = document.getElementById(\"ipo-table-visible-count\");\n      if (!tbody) return;\n\n      tbody.innerHTML = \"\";\n      let list = benchmarkListedIpos;\n\n      if (ipoSearchQuery) {\n        list = list.filter(i => (i.name + \" \" + i.ticker).toLowerCase().includes(ipoSearchQuery));\n      }\n\n      if (countLabel) countLabel.textContent = list.length;\n\n      list.forEach((item, idx) => {\n        const listGainPct = (((item.listPrice - item.issuePrice) / item.issuePrice) * 100).toFixed(1);\n        const totalGainPct = (((item.cmp - item.issuePrice) / item.issuePrice) * 100).toFixed(1);\n        const isListPos = listGainPct >= 0;\n        const isTotalPos = totalGainPct >= 0;\n\n        const tr = document.createElement(\"tr\");\n        tr.className = \"hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors\";\n        tr.innerHTML = `\n          <td class=\"py-3 px-3 text-center font-mono font-bold text-slate-400\">${idx + 1}</td>\n          <td class=\"py-3 px-3\">\n            <div class=\"font-bold text-[#090D16] dark:text-white leading-tight\">${item.name}</div>\n            <div class=\"flex items-center gap-1.5 mt-0.5\">\n              <span class=\"text-[10.5px] font-mono font-bold text-indigo-600 dark:text-indigo-400\">${item.ticker}</span>\n              <span class=\"text-[10px] text-slate-400\">${item.exchange}</span>\n            </div>\n          </td>\n          <td class=\"py-3 px-3 font-mono text-[12px] text-slate-600 dark:text-slate-300\">${item.date}</td>\n          <td class=\"py-3 px-3 font-mono font-bold text-slate-900 dark:text-slate-100\">\u20b9${item.issuePrice}</td>\n          <td class=\"py-3 px-3 font-mono font-bold text-slate-900 dark:text-slate-100\">\u20b9${item.listPrice}</td>\n          <td class=\"py-3 px-3 font-mono font-bold ${isListPos ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600'}\">\n            <span>${isListPos ? '+' : ''}${listGainPct}%</span>\n            <span class=\"text-[10px] text-slate-400 block font-normal\">(+\u20b9${item.listPrice - item.issuePrice})</span>\n          </td>\n          <td class=\"py-3 px-3 font-mono font-bold text-slate-900 dark:text-slate-100\">\u20b9${item.cmp}</td>\n          <td class=\"py-3 px-3 font-mono font-bold ${isTotalPos ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600'}\">\n            <span>${isTotalPos ? '+' : ''}${totalGainPct}%</span>\n            <span class=\"text-[10px] text-slate-400 block font-normal\">(+\u20b9${item.cmp - item.issuePrice})</span>\n          </td>\n          <td class=\"py-3 px-3\">\n            <span class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold ${totalGainPct > 50 ? 'bg-amber-100 text-amber-950 dark:bg-amber-950 dark:text-amber-300 border border-amber-300' : 'bg-emerald-100 text-emerald-950 dark:bg-emerald-950 dark:text-emerald-300 border border-emerald-300'}\">\n              ${totalGainPct > 50 ? '\ud83d\udd25 MULTIBAGGER' : '\ud83d\udfe2 PREMIUM'}\n            </span>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function openStoryModalById(storyId) {\n      const s = (stories || []).find(st => st.id === storyId) || stories[0];\n      if (s) showStoryModal(s);\n    }\n\n\n\n    function showStoryModal(story) {\n      if (!story) return;\n      const modal = document.getElementById(\"story-modal\");\n      if (!modal) return;\n\n      const catEl = document.getElementById(\"story-modal-category\");\n      const sentEl = document.getElementById(\"story-modal-sentiment\");\n      const pageEl = document.getElementById(\"story-modal-pages\");\n      const hlEl = document.getElementById(\"story-modal-headline\");\n      const tickersEl = document.getElementById(\"story-modal-tickers-container\");\n      const briefEl = document.getElementById(\"story-modal-brief\");\n      const catBoxEl = document.getElementById(\"story-modal-catalyst\");\n      const bullEl = document.getElementById(\"story-modal-bullets\");\n      const srcEl = document.getElementById(\"story-modal-source\");\n\n      if (catEl) catEl.textContent = story.category || \"General\";\n      if (sentEl) {\n        const isBull = (story.sentiment || \"\").includes(\"BULLISH\");\n        const isBear = (story.sentiment || \"\").includes(\"BEARISH\");\n        sentEl.className = `px-2 py-0.5 rounded text-[10.5px] font-mono font-bold ${\n          isBull ? \"bg-emerald-50 text-emerald-800 border border-emerald-200 dark:bg-emerald-950 dark:text-emerald-300\" :\n          isBear ? \"bg-rose-50 text-rose-800 border border-rose-200 dark:bg-rose-950 dark:text-rose-300\" :\n          \"bg-slate-100 text-slate-800 border border-slate-200 dark:bg-slate-800 dark:text-slate-200\"\n        }`;\n        sentEl.textContent = story.sentiment || \"NEUTRAL\";\n      }\n      if (pageEl) pageEl.textContent = formatPageSource(story.page_numbers || \"FE / BS\");\n      if (hlEl) hlEl.textContent = story.headline || \"Story Details\";\n      if (tickersEl) {\n        tickersEl.innerHTML = (story.tickers || []).map(t => `<span class=\"px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-indigo-50 text-indigo-700 border border-indigo-200 dark:bg-indigo-950 dark:text-indigo-300\">${t}</span>`).join(\"\");\n      }\n      if (briefEl) briefEl.innerHTML = `<p class=\"text-xs text-slate-700 dark:text-slate-300 leading-relaxed font-normal\">${story.brief_details || story.brief || \"\"}</p>`;\n      if (catBoxEl) catBoxEl.innerHTML = story.catalyst || story.brief_details || \"\";\n      if (bullEl) {\n        const pts = story.bullet_points || story.detailed_points || [];\n        bullEl.innerHTML = pts.map(p => `<li class=\"flex items-start gap-1.5 text-xs text-[#3E2B1E] dark:text-[#E2D8CC] leading-relaxed\"><span class=\"text-amber-800 shrink-0 font-bold\">\u2022</span><span>${p}</span></li>`).join(\"\");\n      }\n      if (srcEl) srcEl.textContent = (story.source_paper || \"FE / BS\") + \" Intelligence\";\n\n      modal.classList.remove(\"hidden\");\n      modal.classList.add(\"flex\");\n    }\n\n    function closeStoryModal() {\n      const modal = document.getElementById(\"story-modal\");\n      if (modal) {\n        modal.classList.add(\"hidden\");\n        modal.classList.remove(\"flex\");\n      }\n    }\n\n    function openIpoModal(item) {\n      if (!item) return;\n      const modal = document.getElementById(\"ipo-modal\");\n      if (!modal) return;\n      const compEl = document.getElementById(\"modal-ipo-company\");\n      const exchEl = document.getElementById(\"modal-ipo-exchange\");\n      const stageEl = document.getElementById(\"modal-ipo-stage\");\n      const priceEl = document.getElementById(\"modal-ipo-price\");\n      const sizeEl = document.getElementById(\"modal-ipo-size\");\n      const lotEl = document.getElementById(\"modal-ipo-lot\");\n      const subEl = document.getElementById(\"modal-ipo-sub\");\n      const descEl = document.getElementById(\"modal-ipo-desc\");\n\n      if (compEl) compEl.textContent = item.company || \"IPO Issue\";\n      if (exchEl) exchEl.textContent = item.exchange || \"NSE / BSE\";\n      if (stageEl) stageEl.textContent = item.stage || \"DRHP\";\n      if (priceEl) priceEl.textContent = item.priceBand || item.issuePrice || \"\u20b9--\";\n      if (sizeEl) sizeEl.textContent = item.size || \"\u20b9--\";\n      if (lotEl) lotEl.textContent = item.lotSize || \"--\";\n      if (subEl) subEl.textContent = item.subscription || item.demand || \"--\";\n      if (descEl) descEl.textContent = item.details || item.brief || item.headline || \"\";\n\n      modal.classList.remove(\"hidden\");\n      modal.classList.add(\"flex\");\n    }\n\n    function closeIpoModal() {\n      const modal = document.getElementById(\"ipo-modal\");\n      if (modal) {\n        modal.classList.add(\"hidden\");\n        modal.classList.remove(\"flex\");\n      }\n    }\n\n    function copyStoryById(storyId) {\n      const s = (stories || []).find(st => st.id === storyId);\n      if (!s) return;\n      const lines = [\n        s.headline || '',\n        '',\n        'Key Details:',\n        s.brief_details || s.brief || '',\n        '',\n        'Bullet Points:'\n      ];\n      (s.bullet_points || []).forEach(b => lines.push('- ' + b));\n      lines.push('');\n      lines.push('Source: ' + (s.page_numbers || 'FE / BS') + ' | Sentiment: ' + (s.sentiment || ''));\n      copyToClipboard(lines.join('\\n'));\n    }\n\n    function renderIpoTable() {\n      renderIpoTrackerTable();\n    }\n\n    function renderCorporateDeskTable() {\n      renderFeedList();\n    }\n\n  </script>\n</body>\n</html>";

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // Handle CORS preflight
    if (request.method === 'OPTIONS') {
      return new Response(null, {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type, Authorization'
        }
      });
    }

    // API: Trigger GitHub Actions Pipeline Endpoint
    if (url.pathname === '/api/trigger-pipeline' && request.method === 'POST') {
      try {
        let payload = {};
        try { payload = await request.json(); } catch(e) {}
        const token = payload.token || env.GH_TOKEN || env.GITHUB_TOKEN;
        
        if (!token) {
          return new Response(JSON.stringify({
            success: false,
            needsToken: true,
            error: 'GitHub Personal Access Token is required to trigger GitHub Actions.'
          }), {
            status: 401,
            headers: {
              'Content-Type': 'application/json; charset=utf-8',
              'Access-Control-Allow-Origin': '*'
            }
          });
        }

        const workflow = payload.workflow || '2_fetch_business_standard.yml';
        const ghResp = await fetch(`https://api.github.com/repos/vedarthain/FinPress/actions/workflows/${workflow}/dispatches`, {
          method: 'POST',
          headers: {
            'Accept': 'application/vnd.github.v3+json',
            'Authorization': `Bearer ${token}`,
            'User-Agent': 'FinPress-Cloudflare-Worker',
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ ref: 'main' })
        });

        if (ghResp.status === 204 || ghResp.ok) {
          return new Response(JSON.stringify({
            success: true,
            message: 'GitHub Actions workflow triggered successfully!'
          }), {
            headers: {
              'Content-Type': 'application/json; charset=utf-8',
              'Access-Control-Allow-Origin': '*'
            }
          });
        } else {
          const errText = await ghResp.text();
          return new Response(JSON.stringify({
            success: false,
            error: `GitHub API returned status ${ghResp.status}: ${errText}`
          }), {
            status: ghResp.status,
            headers: {
              'Content-Type': 'application/json; charset=utf-8',
              'Access-Control-Allow-Origin': '*'
            }
          });
        }
      } catch (err) {
        return new Response(JSON.stringify({
          success: false,
          error: err.message
        }), {
          status: 500,
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*'
          }
        });
      }
    }

    // API: Web Cron Job Trigger Endpoint (Supports simple GET/POST for cron-job.org / EasyCron)
    if (url.pathname === '/api/cron' || url.pathname === '/api/trigger-cron') {
      const token = url.searchParams.get('token') || env.GH_TOKEN || env.GITHUB_TOKEN;
      if (!token) {
        return new Response(JSON.stringify({
          success: false,
          error: 'Missing token. Pass ?token=YOUR_GITHUB_PAT in the cron URL, or configure GH_TOKEN in Cloudflare.'
        }), {
          status: 401,
          headers: { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' }
        });
      }

      try {
        const ghResp = await fetch('https://api.github.com/repos/vedarthain/FinPress/actions/workflows/daily_master_pipeline.yml/dispatches', {
          method: 'POST',
          headers: {
            'Accept': 'application/vnd.github.v3+json',
            'Authorization': `Bearer ${token}`,
            'User-Agent': 'FinPress-Web-Cron',
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ ref: 'main' })
        });

        const ok = ghResp.status === 204 || ghResp.ok;
        return new Response(JSON.stringify({
          success: ok,
          timestamp: new Date().toISOString(),
          message: ok ? '⚡ Daily Master Newspaper Pipeline triggered successfully via Web Cron!' : `GitHub API status: ${ghResp.status}`
        }), {
          headers: { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' }
        });
      } catch (err) {
        return new Response(JSON.stringify({ success: false, error: err.message }), {
          status: 500,
          headers: { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' }
        });
      }
    }

    // API: Business Standard 1-Click Session Sync Endpoint
    if (url.pathname === '/api/session/bs' && request.method === 'POST') {
      try {
        const payload = await request.json();
        let cookiesList = [];

        if (Array.isArray(payload.cookies)) {
          cookiesList = payload.cookies;
        } else if (payload.cookieString || typeof payload === 'string' || payload.cookies) {
          const rawStr = payload.cookieString || payload.cookies || (typeof payload === 'string' ? payload : '');
          const parts = rawStr.split(';').map(p => p.trim()).filter(Boolean);
          for (const part of parts) {
            const eqIdx = part.indexOf('=');
            if (eqIdx > 0) {
              const name = part.substring(0, eqIdx).trim();
              const value = part.substring(eqIdx + 1).trim();
              cookiesList.push({
                name: name,
                value: value,
                domain: '.business-standard.com',
                path: '/',
                expires: -1,
                httpOnly: false,
                secure: true,
                sameSite: 'Lax'
              });
            }
          }
        }

        const storageState = {
          cookies: cookiesList,
          origins: [
            {
              origin: 'https://epaper.business-standard.com',
              localStorage: []
            },
            {
              origin: 'https://www.business-standard.com',
              localStorage: []
            }
          ]
        };

        // Write directly to Cloudflare R2 bucket binding
        if (env.BUCKET) {
          await env.BUCKET.put('sessions/bs_storage_state.json', JSON.stringify(storageState, null, 2), {
            httpMetadata: {
              contentType: 'application/json; charset=utf-8'
            }
          });
        }

        // Trigger GitHub Actions repository_dispatch if token is configured
        let gaTriggered = false;
        const ghToken = payload.token || env.GH_TOKEN || env.GITHUB_TOKEN;
        if (ghToken) {
          try {
            const ghResp = await fetch('https://api.github.com/repos/vedarthain/FinPress/actions/workflows/2_fetch_business_standard.yml/dispatches', {
              method: 'POST',
              headers: {
                'Accept': 'application/vnd.github.v3+json',
                'Authorization': `Bearer ${ghToken}`,
                'User-Agent': 'FinPress-Cloudflare-Worker',
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({ ref: 'main' })
            });
            gaTriggered = (ghResp.status === 204 || ghResp.ok);
          } catch (ghErr) {
            console.error('GH Dispatch error:', ghErr);
          }
        }

        return new Response(JSON.stringify({
          success: true,
          message: 'Business Standard session synced to Cloudflare R2 successfully!',
          cookiesCount: cookiesList.length,
          gaTriggered: gaTriggered
        }), {
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type, Authorization'
          }
        });
      } catch (err) {
        return new Response(JSON.stringify({
          success: false,
          error: err.message || 'Failed to process session payload'
        }), {
          status: 400,
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*'
          }
        });
      }
    }

    // API proxy to Cloudflare R2 / latest report
    if (url.pathname === '/api/latest' || url.pathname.startsWith('/api/report')) {
      const dateParam = url.searchParams.get('date');
      const targetFile = dateParam ? `news_report_unified_${dateParam}.json` : 'news_report_unified_latest.json';
      const r2Url = `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/${targetFile}?t=${Date.now()}`;
      try {
        const resp = await fetch(r2Url, {
          headers: { 'User-Agent': 'FinPress-Cloudflare-Worker' },
          cf: { cacheTtl: 0, cacheEverything: false }
        });
        return new Response(resp.body, {
          status: resp.status,
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            'Pragma': 'no-cache',
            'Expires': '0'
          }
        });
      } catch (e) {
        return new Response(JSON.stringify({ error: 'Failed to fetch report' }), { status: 500 });
      }
    }

    if (url.pathname === '/api/dates') {
      let dates = [];
      try {
        const listed = await env.BUCKET.list({ prefix: 'reports/news_report_unified_' });
        dates = listed.objects
          .map(o => o.key.match(/news_report_unified_(\d{4}-\d{2}-\d{2})\.json$/))
          .filter(Boolean)
          .map(m => m[1])
          .sort()
          .reverse();
      } catch (e) {
        console.error('Failed to list R2 dates:', e);
      }
      return new Response(JSON.stringify(dates), {
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
          'Cache-Control': 'no-cache, no-store, must-revalidate'
        }
      });
    }

    // API: R2 Storage Housekeeping & 3GB Quota Management
    if (url.pathname === '/api/housekeeping/r2') {
      try {
        if (!env.BUCKET) {
          return new Response(JSON.stringify({ error: 'R2 BUCKET binding not found' }), { status: 500 });
        }

        const maxLimitBytes = 3 * 1024 * 1024 * 1024; // 3.0 GB Hard Threshold
        const targetBytes = Math.floor(2.2 * 1024 * 1024 * 1024); // 2.2 GB Target

        let objects = [];
        let cursor = undefined;
        do {
          const listed = await env.BUCKET.list({ cursor, limit: 1000 });
          objects = objects.concat(listed.objects);
          cursor = listed.truncated ? listed.cursor : undefined;
        } while (cursor);

        let totalBytes = objects.reduce((acc, o) => acc + o.size, 0);
        let categories = { pdfs: 0, reports: 0, cutouts: 0, sessions: 0, other: 0 };
        
        objects.forEach(o => {
          const k = o.key.toLowerCase();
          if (k.startsWith('pdfs/') || k.endsWith('.pdf')) categories.pdfs += o.size;
          else if (k.startsWith('reports/') || k.endsWith('.json') || k.endsWith('.md')) categories.reports += o.size;
          else if (k.startsWith('cutouts/') || k.endsWith('.png') || k.endsWith('.jpg')) categories.cutouts += o.size;
          else if (k.startsWith('sessions/')) categories.sessions += o.size;
          else categories.other += o.size;
        });

        const shouldPrune = url.searchParams.get('prune') === 'true' || totalBytes > maxLimitBytes;
        let deletedKeys = [];
        let freedBytes = 0;

        if (shouldPrune) {
          const allKeySet = new Set(objects.map(o => o.key));
          
          // 1. Root duplicate PDFs
          for (const o of objects) {
            if (!o.key.startsWith('pdfs/') && o.key.endsWith('.pdf') && allKeySet.has('pdfs/' + o.key)) {
              deletedKeys.push(o.key);
              freedBytes += o.size;
            }
          }

          // 2. Oldest PDFs if still over target
          let projectedBytes = totalBytes - freedBytes;
          if (projectedBytes > targetBytes) {
            const candidatePdfs = objects
              .filter(o => (o.key.startsWith('pdfs/') || o.key.endsWith('.pdf')) && !deletedKeys.includes(o.key))
              .sort((a, b) => new Date(a.uploaded).getTime() - new Date(b.uploaded).getTime());

            for (const o of candidatePdfs) {
              if (projectedBytes <= targetBytes) break;
              deletedKeys.push(o.key);
              freedBytes += o.size;
              projectedBytes -= o.size;
            }
          }

          if (deletedKeys.length > 0) {
            await Promise.all(deletedKeys.map(k => env.BUCKET.delete(k)));
          }
        }

        const finalTotalBytes = totalBytes - freedBytes;

        return new Response(JSON.stringify({
          success: true,
          status: finalTotalBytes > maxLimitBytes ? 'EXCEEDED' : 'HEALTHY',
          limit_gb: 3.0,
          current_total_mb: Math.round((finalTotalBytes / (1024 * 1024)) * 100) / 100,
          current_total_gb: Math.round((finalTotalBytes / (1024 * 1024 * 1024)) * 10000) / 10000,
          headroom_gb: Math.round(((maxLimitBytes - finalTotalBytes) / (1024 * 1024 * 1024)) * 100) / 100,
          categories_mb: {
            pdfs: Math.round((categories.pdfs / (1024 * 1024)) * 100) / 100,
            reports: Math.round((categories.reports / (1024 * 1024)) * 100) / 100,
            cutouts: Math.round((categories.cutouts / (1024 * 1024)) * 100) / 100,
            sessions: Math.round((categories.sessions / (1024 * 1024)) * 100) / 100,
            other: Math.round((categories.other / (1024 * 1024)) * 100) / 100
          },
          pruned_count: deletedKeys.length,
          freed_mb: Math.round((freedBytes / (1024 * 1024)) * 100) / 100
        }, null, 2), {
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
            'Cache-Control': 'no-cache, no-store, must-revalidate'
          }
        });
      } catch (err) {
        return new Response(JSON.stringify({ success: false, error: err.message }), {
          status: 500,
          headers: { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' }
        });
      }
    }

    // Default: Serve Trader Terminal UI
    return new Response(HTML, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache, no-store, must-revalidate, max-age=0',
        'Pragma': 'no-cache',
        'Expires': '0'
      }
    });
  },

  // Automatic Cloudflare Cron Trigger (Runs daily at 5:45 AM & 6:15 AM IST + R2 Housekeeping)
  async scheduled(event, env, ctx) {
    // 1. Enforce R2 3GB Quota Housekeeping
    if (env.BUCKET) {
      try {
        let objects = [];
        let cursor = undefined;
        do {
          const listed = await env.BUCKET.list({ cursor, limit: 1000 });
          objects = objects.concat(listed.objects);
          cursor = listed.truncated ? listed.cursor : undefined;
        } while (cursor);

        const maxLimitBytes = 3 * 1024 * 1024 * 1024;
        const targetBytes = Math.floor(2.2 * 1024 * 1024 * 1024);
        let totalBytes = objects.reduce((acc, o) => acc + o.size, 0);

        if (totalBytes > targetBytes) {
          const candidatePdfs = objects
            .filter(o => o.key.startsWith('pdfs/') || o.key.endsWith('.pdf'))
            .sort((a, b) => new Date(a.uploaded).getTime() - new Date(b.uploaded).getTime());

          let keysToDelete = [];
          let freed = 0;
          for (const o of candidatePdfs) {
            if (totalBytes - freed <= targetBytes) break;
            keysToDelete.push(o.key);
            freed += o.size;
          }
          if (keysToDelete.length > 0) {
            await Promise.all(keysToDelete.map(k => env.BUCKET.delete(k)));
            console.log(`Cloudflare Cron R2 Housekeeping: Pruned ${keysToDelete.length} items, freed ${Math.round(freed/1024/1024)} MB.`);
          }
        }
      } catch (e) {
        console.error('Cloudflare Cron R2 Housekeeping error:', e);
      }
    }

    // 2. Trigger Daily Master Pipeline
    const ghToken = env.GH_TOKEN || env.GITHUB_TOKEN;
    if (ghToken) {
      try {
        await fetch('https://api.github.com/repos/vedarthain/FinPress/actions/workflows/daily_master_pipeline.yml/dispatches', {
          method: 'POST',
          headers: {
            'Accept': 'application/vnd.github.v3+json',
            'Authorization': `Bearer ${ghToken}`,
            'User-Agent': 'FinPress-Cloudflare-Cron',
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ ref: 'main' })
        });
      } catch(err) {
        console.error('Cloudflare Cron Trigger error:', err);
      }
    }
  }
};
